import React, { useState, useEffect, useRef } from 'react';
import {
  Film,
  Tv,
  Flame,
  Bookmark,
  History,
  Play,
  Trash2,
  Sparkles,
  Info,
  Layers,
  Star,
  Search,
  Loader2,
  X,
  SlidersHorizontal,
  BookOpen,
} from 'lucide-react';
import { MediaItem, WatchHistoryItem, AppSettings } from './types';
import {
  DEFAULT_TMDB_API_KEY,
  fetchTrending,
  fetchPopular,
  fetchTopRated,
  fetchByGenre,
  fetchAnime,
  searchCatalog,
  fetchDetails,
  fetchTVDetails,
  GENRE_MAP,
  getPosterUrl,
} from './services/tmdb';
import { Navbar } from './components/Navbar';
import { HeroBanner } from './components/HeroBanner';
import { MediaCarousel } from './components/MediaCarousel';
import { CinemaPlayer } from './components/CinemaPlayer';
import { MediaDetailModal } from './components/MediaDetailModal';
import { TrailerModal } from './components/TrailerModal';
import { SettingsModal } from './components/SettingsModal';
import { triggerNativeOGAdsLocker, triggerActiveLocker } from './utils/locker';
import { AdminLoginModal } from './components/admin/AdminLoginModal';
import { AdminDashboard } from './components/admin/AdminDashboard';
import { LockerModal } from './components/LockerModal';
import { ArticlesHub } from './components/ArticlesHub';
import { adminAuth } from './services/adminAuth';
import { liveTracker } from './services/liveTracker';

const CATEGORIES = ['All', 'Action', 'Comedy', 'Horror', 'Sci-Fi', 'Drama'];

export default function App() {
  // Navigation & Active View
  const [currentTab, setCurrentTab] = useState<'home' | 'movies' | 'tv' | 'anime' | 'trending' | 'watchlist' | 'history' | 'search' | 'articles'>('home');
  const [selectedArticleSlug, setSelectedArticleSlug] = useState<string | null>(null);
  const [activeMedia, setActiveMedia] = useState<MediaItem | null>(null);
  const [playerSeason, setPlayerSeason] = useState(1);
  const [playerEpisode, setPlayerEpisode] = useState(1);

  // Search View State
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<MediaItem[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [searchFilter, setSearchFilter] = useState<'all' | 'movie' | 'tv'>('all');

  // Modals
  const [detailMedia, setDetailMedia] = useState<MediaItem | null>(null);
  const [trailerMedia, setTrailerMedia] = useState<MediaItem | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [isAdminLoginOpen, setIsAdminLoginOpen] = useState(false);
  const [isAdminDashboardOpen, setIsAdminDashboardOpen] = useState(false);

  // Data Collections
  const [heroMedia, setHeroMedia] = useState<MediaItem | null>(null);
  const [trendingAll, setTrendingAll] = useState<MediaItem[]>([]);
  const [trendingMovies, setTrendingMovies] = useState<MediaItem[]>([]);
  const [trendingTV, setTrendingTV] = useState<MediaItem[]>([]);
  const [popularMovies, setPopularMovies] = useState<MediaItem[]>([]);
  const [topRatedMovies, setTopRatedMovies] = useState<MediaItem[]>([]);
  const [actionMovies, setActionMovies] = useState<MediaItem[]>([]);
  const [sciFiMovies, setSciFiMovies] = useState<MediaItem[]>([]);
  const [genreFilteredItems, setGenreFilteredItems] = useState<MediaItem[]>([]);

  // Anime Collection
  const [animeCarouselItems, setAnimeCarouselItems] = useState<MediaItem[]>([]);
  const [animeCatalogItems, setAnimeCatalogItems] = useState<MediaItem[]>([]);
  const [animeFilter, setAnimeFilter] = useState<'all' | 'series' | 'movies'>('all');
  const [loadingAnime, setLoadingAnime] = useState(false);

  // Filtering
  const [activeCategory, setActiveCategory] = useState('All');
  const [catalogType, setCatalogType] = useState<'movie' | 'tv'>('movie');

  // Watchlist & History
  const [watchlist, setWatchlist] = useState<MediaItem[]>(() => {
    try {
      const saved = localStorage.getItem('flixstream_watchlist');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [history, setHistory] = useState<WatchHistoryItem[]>(() => {
    try {
      const saved = localStorage.getItem('flixstream_history');
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  // Settings
  const [settings, setSettings] = useState<AppSettings>(() => {
    try {
      const saved = localStorage.getItem('flixstream_settings');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (parsed.lockerId === 'o4e2pq' || parsed.lockerId === 'o4e5p2') parsed.lockerId = '4o7vvr';
        return parsed;
      }
    } catch {
      // ignore
    }
    return {
      tmdbApiKey: DEFAULT_TMDB_API_KEY,
      lockerEnabled: true,
      lockerId: '4o7vvr',
      lockerDelaySeconds: 20,
    };
  });

  // Dynamic Tab SEO Optimization (Titles & Descriptions for high Google Rankings)
  useEffect(() => {
    if (activeMedia) return; // CinemaPlayer handles its own media SEO

    const SEO_TAB_CONFIG: Record<string, { title: string; desc: string }> = {
      home: {
        title: 'BleuStream – Watch Free Movies, TV Shows & Anime in Ultra HD',
        desc: 'Stream thousands of blockbuster movies, full TV series, and trending anime in 4K & 1080p Ultra HD on BleuStream. 7 high-speed servers, stereo audio, and zero subscription.',
      },
      movies: {
        title: 'Watch Free Movies Online in 1080p & 4K HD – BleuStream Cinema',
        desc: 'Explore the latest box-office releases, action blockbusters, comedies, and classic cinema free in full HD on BleuStream. Zero buffer with direct VIP servers.',
      },
      tv: {
        title: 'Stream Full TV Shows & Complete Series Free Online – BleuStream',
        desc: 'Binge-watch complete TV seasons, trending series, and award-winning dramas with all episodes available in 1080p Ultra HD on BleuStream.',
      },
      anime: {
        title: 'Watch Trending Anime Online in HD with English Subtitles – BleuStream',
        desc: 'Watch top anime series, new seasonal episodes, and anime movies in crisp HD with multi-server playback on BleuStream.',
      },
      trending: {
        title: 'Top Trending Movies & Viral TV Shows Today – BleuStream',
        desc: 'Discover what everyone is watching right now. Daily updated top-rated movies, box-office hits, and trending TV series streaming free in 4K.',
      },
      watchlist: {
        title: 'My Free Cinema Watchlist – BleuStream',
        desc: 'Access your saved movies and TV shows anytime on BleuStream. Unlimited free cinema streaming.',
      },
      history: {
        title: 'Continue Watching & Stream History – BleuStream',
        desc: 'Pick up right where you left off. Continue watching your favorite movies and TV episodes on BleuStream.',
      },
      search: {
        title: searchQuery ? `Search: "${searchQuery}" – BleuStream Cinema` : 'Search Movies & TV Shows – BleuStream',
        desc: `Explore and stream full-length movies, TV series, and anime titles matching "${searchQuery || 'all'}" in 1080p Ultra HD on BleuStream.`,
      },
    };

    const tabSeo = SEO_TAB_CONFIG[currentTab] || SEO_TAB_CONFIG.home;
    document.title = tabSeo.title;

    const metaDesc = document.querySelector('meta[name="description"]');
    if (metaDesc) metaDesc.setAttribute('content', tabSeo.desc);

    const ogTitle = document.querySelector('meta[property="og:title"]');
    if (ogTitle) ogTitle.setAttribute('content', tabSeo.title);

    const ogDesc = document.querySelector('meta[property="og:description"]');
    if (ogDesc) ogDesc.setAttribute('content', tabSeo.desc);

    const twTitle = document.querySelector('meta[name="twitter:title"]');
    if (twTitle) twTitle.setAttribute('content', tabSeo.title);

    const twDesc = document.querySelector('meta[name="twitter:description"]');
    if (twDesc) twDesc.setAttribute('content', tabSeo.desc);
  }, [currentTab, activeMedia]);

  // CPA 15-second timer reference
  const lockerTimerRef = useRef<NodeJS.Timeout | null>(null);

  // Sync state to localStorage
  useEffect(() => {
    localStorage.setItem('flixstream_watchlist', JSON.stringify(watchlist));
  }, [watchlist]);

  useEffect(() => {
    localStorage.setItem('flixstream_history', JSON.stringify(history));
  }, [history]);

  useEffect(() => {
    localStorage.setItem('flixstream_settings', JSON.stringify(settings));
  }, [settings]);

  // Clean legacy persistent unlock keys from localStorage so 10-second locker works on test sessions
  useEffect(() => {
    try {
      Object.keys(localStorage).forEach((key) => {
        if (key.startsWith('unlocked_') || key.startsWith('flixstream_unlocked_')) {
          localStorage.removeItem(key);
        }
      });
    } catch {
      // ignore
    }

    try {
      const params = new URLSearchParams(window.location.search);
      const tabParam = params.get('tab');
      if (tabParam && ['home', 'movies', 'tv', 'anime', 'trending', 'watchlist', 'history', 'articles'].includes(tabParam)) {
        setCurrentTab(tabParam as any);
      }
      const articleParam = params.get('article');
      if (articleParam) {
        setSelectedArticleSlug(articleParam);
        setCurrentTab('articles');
      }
      const searchParam = params.get('search');
      if (searchParam) {
        setSearchQuery(searchParam);
        setCurrentTab('search');
        setIsSearching(true);
        searchCatalog(searchParam).then((res) => {
          setSearchResults(res);
          setIsSearching(false);
        });
      }

      const watchParam = params.get('watch');
      if (watchParam) {
        const id = parseInt(watchParam, 10);
        const s = parseInt(params.get('season') || '1', 10);
        const e = parseInt(params.get('episode') || '1', 10);
        if (!isNaN(id)) {
          fetchDetails('movie', id)
            .then((m) => {
              if (m && m.id) {
                handlePlayMedia(m, s, e);
              } else {
                fetchTVDetails(id).then((tv) => {
                  if (tv && tv.id) handlePlayMedia(tv, s, e);
                });
              }
            })
            .catch(() => {
              fetchTVDetails(id).then((tv) => {
                if (tv && tv.id) handlePlayMedia(tv, s, e);
              });
            });
        }
      }

      // Secret Admin URL Query: ?admin=... or ?vault=true
      const adminParam = params.get('admin') || params.get('vault');
      if (adminParam) {
        if (adminAuth.getState().isAuthenticated) {
          setIsAdminDashboardOpen(true);
        } else {
          setIsAdminLoginOpen(true);
        }
      }
    } catch (e) {
      // ignore
    }

    // Record page view in live telemetry tracker
    liveTracker.recordPageView();

    // Secret Admin Keyboard Shortcut: Ctrl + Shift + A (or Cmd + Shift + A)
    const handleAdminKey = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.shiftKey && (e.key === 'A' || e.key === 'a')) {
        e.preventDefault();
        if (adminAuth.getState().isAuthenticated) {
          setIsAdminDashboardOpen(true);
        } else {
          setIsAdminLoginOpen(true);
        }
      }
    };

    window.addEventListener('keydown', handleAdminKey);
    return () => window.removeEventListener('keydown', handleAdminKey);
  }, []);

  // Initial TMDB Data Load
  useEffect(() => {
    const loadData = async () => {
      try {
        const [trending, popMovies, popTV, topMovies, action, sciFi, animeList] = await Promise.all([
          fetchTrending('all', 'day'),
          fetchPopular('movie'),
          fetchPopular('tv'),
          fetchTopRated('movie'),
          fetchByGenre('movie', GENRE_MAP['Action'].movie),
          fetchByGenre('movie', GENRE_MAP['Sci-Fi'].movie),
          fetchAnime('all', 1),
        ]);

        setTrendingAll(trending);
        setTrendingMovies(trending.filter((i) => i.media_type === 'movie' || !i.first_air_date));
        setTrendingTV(popTV);
        setPopularMovies(popMovies);
        setTopRatedMovies(topMovies);
        setActionMovies(action);
        setSciFiMovies(sciFi);
        setAnimeCarouselItems(animeList);
        setAnimeCatalogItems(animeList);

        if (trending.length > 0) {
          // Choose an engaging movie/show with poster & backdrop for Hero
          const candidate = trending.find((i) => i.backdrop_path && i.overview) || trending[0];
          setHeroMedia(candidate);
        }
      } catch (err) {
        console.error('Error loading initial catalog data:', err);
      }
    };

    loadData();
  }, [settings.tmdbApiKey]);

  // Load Anime catalog when user switches to Anime tab or changes anime filter
  useEffect(() => {
    if (currentTab === 'anime') {
      setLoadingAnime(true);
      fetchAnime(animeFilter).then((items) => {
        setAnimeCatalogItems(items);
        setLoadingAnime(false);
      });
    }
  }, [currentTab, animeFilter]);

  // Handle category changes in trending/catalog
  const handleSelectCategory = async (category: string) => {
    setActiveCategory(category);
    if (category === 'All') {
      setGenreFilteredItems([]);
      return;
    }

    const mapping = GENRE_MAP[category];
    if (mapping) {
      const genreId = catalogType === 'movie' ? mapping.movie : mapping.tv;
      const results = await fetchByGenre(catalogType, genreId);
      setGenreFilteredItems(results);
    }
  };

  // Watchlist Management
  const watchlistIds = new Set(watchlist.map((item) => item.id));

  const toggleWatchlist = (item: MediaItem) => {
    setWatchlist((prev) => {
      const exists = prev.some((i) => i.id === item.id);
      if (exists) {
        return prev.filter((i) => i.id !== item.id);
      } else {
        return [item, ...prev];
      }
    });
  };

  // Record Stream History
  const addToHistory = (item: MediaItem, season = 1, episode = 1) => {
    setHistory((prev) => {
      const filtered = prev.filter((h) => h.id !== item.id);
      const isTv = item.media_type === 'tv' || !!item.first_air_date;
      const newEntry: WatchHistoryItem = {
        id: item.id,
        media: item,
        type: isTv ? 'tv' : 'movie',
        season: isTv ? season : undefined,
        episode: isTv ? episode : undefined,
        lastWatched: Date.now(),
      };
      return [newEntry, ...filtered].slice(0, 30);
    });
  };

  // Start Streaming handler
  const handlePlayMedia = (item: MediaItem, season = 1, episode = 1) => {
    setActiveMedia(item);
    setPlayerSeason(season);
    setPlayerEpisode(episode);
    setDetailMedia(null);
    addToHistory(item, season, episode);
    const title = item.title || item.name || 'Untitled';
    liveTracker.recordPageView(`/watch/${item.id}`);
    liveTracker.setWatchingState(true, title);
    // Instant live radar registration upon selecting the film
    liveTracker.recordStreamStart(item, season, episode, 'Server 1: VIP Ultra HD');
  };

  const handlePlayMediaById = async (mediaId: number, type: 'movie' | 'tv', title: string) => {
    try {
      if (type === 'tv') {
        const tv = await fetchTVDetails(mediaId);
        if (tv && tv.id) {
          handlePlayMedia(tv, 1, 1);
          return;
        }
      } else {
        const movie = await fetchDetails('movie', mediaId);
        if (movie && movie.id) {
          handlePlayMedia(movie, 1, 1);
          return;
        }
      }
    } catch {
      // ignore
    }

    const fallbackItem: MediaItem = {
      id: mediaId,
      title: title,
      name: title,
      media_type: type,
      overview: `Streaming ${title} in 1080p and 4K Ultra HD on BleuStream.`,
      poster_path: '',
      backdrop_path: '',
      vote_average: 8.5,
      vote_count: 0,
    };
    handlePlayMedia(fallbackItem, 1, 1);
  };

  // CPA Locker Stream Hook
  const handleStreamStarted = () => {
    // Media stream active
  };

  // Execute global search across entire movies & series catalog
  const handleExecuteSearch = async (query: string) => {
    const cleanQuery = query.trim();
    if (!cleanQuery) return;
    setSearchQuery(cleanQuery);
    setCurrentTab('search');
    setActiveMedia(null);
    setIsSearching(true);
    window.scrollTo({ top: 0, behavior: 'smooth' });
    try {
      const results = await searchCatalog(cleanQuery);
      setSearchResults(results);
    } catch (err) {
      console.error('Search error:', err);
    } finally {
      setIsSearching(false);
    }
  };

  // Trigger test locker from settings
  const handleTriggerTestLocker = () => {
    triggerActiveLocker();
    setShowSettings(false);
  };

  return (
    <div className="min-h-screen bg-[#141414] text-white flex flex-col font-sans">
      {/* Top Floating Navbar */}
      <Navbar
        currentTab={currentTab}
        onSelectTab={(tab) => {
          setCurrentTab(tab);
          liveTracker.recordPageView(tab === 'home' ? '/' : `/${tab}`);
          if (activeMedia) {
            setActiveMedia(null);
            liveTracker.setWatchingState(false);
          }
        }}
        onOpenMedia={(item) => {
          handlePlayMedia(item);
        }}
        onSearchSubmit={handleExecuteSearch}
        onOpenSettings={() => setShowSettings(true)}
        watchlistCount={watchlist.length}
      />

      {/* Main Content Area */}
      <main className="flex-1">
        {/* If Active Player is Playing */}
        {activeMedia ? (
          <CinemaPlayer
            media={activeMedia}
            initialSeason={playerSeason}
            initialEpisode={playerEpisode}
            onBack={() => setActiveMedia(null)}
            onSelectSimilar={(item) => handlePlayMedia(item)}
            onStreamStarted={handleStreamStarted}
          />
        ) : (
          <>
            {/* View: Home */}
            {currentTab === 'home' && (
              <div className="space-y-6 pb-20">
                <HeroBanner
                  media={heroMedia}
                  onWatchNow={(item) => handlePlayMedia(item)}
                  onOpenInfo={(item) => setDetailMedia(item)}
                  onToggleWatchlist={toggleWatchlist}
                  isInWatchlist={heroMedia ? watchlistIds.has(heroMedia.id) : false}
                />

                {/* Continue Watching (if history exists) */}
                {history.length > 0 && (
                  <section className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-2">
                    <div className="flex items-center justify-between mb-3">
                      <h2 className="text-lg sm:text-xl font-bold text-white flex items-center gap-2">
                        <History className="w-5 h-5 text-sky-400" />
                        <span>Continue Watching</span>
                      </h2>
                      <button
                        onClick={() => setCurrentTab('history')}
                        className="text-xs text-cyan-400 hover:text-red-300 transition"
                      >
                        View Full History ({history.length})
                      </button>
                    </div>

                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 sm:gap-4">
                      {history.slice(0, 6).map((item) => (
                        <div
                          key={item.id}
                          onClick={() => handlePlayMedia(item.media, item.season, item.episode)}
                          className="group relative cursor-pointer bg-zinc-900 border border-zinc-800 rounded-xl overflow-hidden hover:border-sky-500 transition"
                        >
                          <div className="aspect-[2/3] w-full relative">
                            <img
                              src={getPosterUrl(item.media.poster_path, 'w500')}
                              alt={item.media.title || item.media.name || 'Poster'}
                              className="w-full h-full object-cover group-hover:scale-105 transition duration-500"
                              loading="lazy"
                            />
                            <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition flex items-center justify-center">
                              <div className="p-3 bg-[#0ea5e9] text-white rounded-full shadow-lg">
                                <Play className="w-4 h-4 fill-white" />
                              </div>
                            </div>
                          </div>
                          <div className="p-2.5">
                            <p className="text-xs font-semibold text-white truncate group-hover:text-cyan-400">
                              {item.media.title || item.media.name}
                            </p>
                            <p className="text-[10px] text-zinc-400 mt-0.5">
                              {item.type === 'tv'
                                ? `Season ${item.season || 1}, Ep ${item.episode || 1}`
                                : 'Full Movie'}
                            </p>
                          </div>
                        </div>
                      ))}
                    </div>
                  </section>
                )}

                {/* Trending Movies Carousel with Category Tabs */}
                <MediaCarousel
                  title="🔥 Trending Movies & TV Series"
                  subtitle="Top watched titles updated every hour"
                  items={genreFilteredItems.length > 0 ? genreFilteredItems : trendingAll}
                  onPlay={(item) => handlePlayMedia(item)}
                  onOpenDetails={(item) => setDetailMedia(item)}
                  onToggleWatchlist={toggleWatchlist}
                  watchlistIds={watchlistIds}
                  categories={CATEGORIES}
                  activeCategory={activeCategory}
                  onSelectCategory={handleSelectCategory}
                />

                {/* Popular Movies */}
                <MediaCarousel
                  title="🎬 Popular Blockbusters"
                  items={popularMovies}
                  onPlay={(item) => handlePlayMedia(item)}
                  onOpenDetails={(item) => setDetailMedia(item)}
