                        className="absolute right-1.5 px-3 py-1 bg-[#0ea5e9] hover:bg-sky-600 text-white text-[11px] font-bold rounded-lg transition cursor-pointer"
                      >
                        {isSearching ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : 'Search'}
                      </button>
                    </form>
                  </div>

                  {/* Filter Tabs: All, Movies, TV Series */}
                  {searchResults.length > 0 && (
                    <div className="flex items-center gap-2 pt-1">
                      {[
                        { id: 'all', label: `All Results (${searchResults.length})` },
                        {
                          id: 'movie',
                          label: `Movies (${searchResults.filter((i) => i.media_type === 'movie' || !i.first_air_date).length})`,
                        },
                        {
                          id: 'tv',
                          label: `TV Series (${searchResults.filter((i) => i.media_type === 'tv' || !!i.first_air_date).length})`,
                        },
                      ].map((tab) => (
                        <button
                          key={tab.id}
                          onClick={() => setSearchFilter(tab.id as 'all' | 'movie' | 'tv')}
                          className={`px-3.5 py-1.5 rounded-full text-xs font-semibold transition cursor-pointer ${
                            searchFilter === tab.id
                              ? 'bg-[#0ea5e9] text-white shadow-md'
                              : 'bg-zinc-800 hover:bg-zinc-700 text-zinc-300'
                          }`}
                        >
                          {tab.label}
                        </button>
                      ))}
                    </div>
                  )}
                </div>

                {/* Loading Skeleton Grid */}
                {isSearching && (
                  <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 sm:gap-4">
                    {Array.from({ length: 12 }).map((_, i) => (
                      <div key={i} className="space-y-2 animate-pulse bg-zinc-900/60 p-2 rounded-xl border border-zinc-800">
                        <div className="aspect-[2/3] w-full bg-zinc-800 rounded-lg" />
                        <div className="h-3.5 bg-zinc-800 rounded w-3/4" />
                        <div className="h-3 bg-zinc-850 rounded w-1/2" />
                      </div>
                    ))}
                  </div>
                )}

                {/* Search Results Grid */}
                {!isSearching && searchResults.length > 0 && (
                  <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 sm:gap-4">
                    {searchResults
                      .filter((item) => {
                        if (searchFilter === 'movie') return item.media_type === 'movie' || !item.first_air_date;
                        if (searchFilter === 'tv') return item.media_type === 'tv' || !!item.first_air_date;
                        return true;
                      })
                      .map((item) => {
                        const title = item.title || item.name || 'Untitled';
                        const year = (item.release_date || item.first_air_date || '').slice(0, 4);
                        const isTv = item.media_type === 'tv' || !!item.first_air_date;
                        const inWatchlist = watchlistIds.has(item.id);

                        return (
                          <div
                            key={item.id}
                            className="group relative space-y-2 bg-zinc-900/60 p-2 rounded-xl border border-zinc-800 hover:border-sky-500 transition"
                          >
                            <div
                              onClick={() => setDetailMedia(item)}
                              className="relative aspect-[2/3] w-full rounded-lg overflow-hidden bg-black shadow cursor-pointer"
                            >
                              <img
                                src={getPosterUrl(item.poster_path, 'w500')}
                                alt={title}
                                className="w-full h-full object-cover group-hover:scale-105 transition duration-500"
                                loading="lazy"
                              />
                              <div className="absolute top-2 left-2 px-1.5 py-0.5 bg-black/80 backdrop-blur-sm text-[9px] font-bold text-zinc-300 rounded uppercase">
                                {isTv ? 'TV Show' : 'Movie'}
                              </div>
                              <div className="absolute top-2 right-2 px-1.5 py-0.5 bg-[#0ea5e9] text-white text-[9px] font-bold rounded">
                                HD
                              </div>

                              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition flex items-center justify-center gap-2">
                                <button
                                  type="button"
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    handlePlayMedia(item);
                                  }}
                                  title="Watch Now"
                                  className="p-3 bg-[#0ea5e9] text-white rounded-full shadow-lg hover:scale-110 active:scale-95 transition cursor-pointer"
                                >
                                  <Play className="w-4 h-4 fill-white" />
                                </button>
                                <button
                                  type="button"
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    toggleWatchlist(item);
                                  }}
                                  title={inWatchlist ? 'Remove from My List' : 'Add to My List'}
                                  className="p-2.5 bg-black/80 hover:bg-black text-white rounded-full transition cursor-pointer"
                                >
                                  <Bookmark className={`w-3.5 h-3.5 ${inWatchlist ? 'fill-red-500 text-sky-400' : ''}`} />
                                </button>
                              </div>
                            </div>

                            <div>
                              <h3
                                onClick={() => setDetailMedia(item)}
                                className="text-xs font-bold text-white truncate cursor-pointer hover:text-cyan-400"
                              >
                                {title}
                              </h3>
                              <div className="flex items-center justify-between text-[10px] text-zinc-400 mt-0.5">
                                <span>{year || '2024'}</span>
                                <span className="flex items-center gap-0.5 text-amber-400 font-semibold">
                                  <Star className="w-2.5 h-2.5 fill-amber-400" />
                                  {item.vote_average?.toFixed(1) || '7.8'}
                                </span>
                              </div>
                            </div>
                          </div>
                        );
                      })}
                  </div>
                )}

                {/* Empty State / Not Found with Recommendations */}
                {!isSearching && searchResults.length === 0 && (
                  <div className="space-y-8 pt-6">
                    <div className="py-12 flex flex-col items-center justify-center text-center space-y-3 bg-zinc-900/40 border border-zinc-800 rounded-2xl p-6">
                      <Search className="w-12 h-12 text-zinc-600" />
                      <h3 className="text-lg font-bold text-zinc-200">
                        {searchQuery ? `No exact matches found for "${searchQuery}"` : 'Type a title to search'}
                      </h3>
                      <p className="text-xs text-zinc-400 max-w-md">
                        Make sure the spelling is correct, or explore trending box-office blockbusters below.
                      </p>
                    </div>

                    <div className="space-y-3">
                      <h3 className="text-sm font-bold text-white flex items-center gap-2">
                        <Flame className="w-4 h-4 text-sky-400" />
                        <span>Popular Movies You Might Like</span>
                      </h3>
                      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 sm:gap-4">
                        {popularMovies.slice(0, 6).map((item) => (
                          <div
                            key={item.id}
                            onClick={() => handlePlayMedia(item)}
                            className="group cursor-pointer space-y-2 bg-zinc-900/60 p-2 rounded-xl border border-zinc-800 hover:border-sky-500 transition"
                          >
                            <div className="aspect-[2/3] w-full rounded-lg overflow-hidden relative">
                              <img
                                src={getPosterUrl(item.poster_path, 'w500')}
                                alt={item.title || 'Movie'}
                                className="w-full h-full object-cover group-hover:scale-105 transition"
                                loading="lazy"
                              />
                              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition flex items-center justify-center">
                                <div className="p-3 bg-[#0ea5e9] text-white rounded-full shadow-lg">
                                  <Play className="w-4 h-4 fill-white" />
                                </div>
                              </div>
                            </div>
                            <h4 className="text-xs font-semibold text-white truncate group-hover:text-cyan-400">
                              {item.title}
                            </h4>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* View: Cinema Guides & SEO Articles */}
            {currentTab === 'articles' && (
              <ArticlesHub
                initialSlug={selectedArticleSlug}
                onPlayMediaById={handlePlayMediaById}
                onBackToHome={() => setCurrentTab('home')}
              />
            )}
          </>
        )}
      </main>

      {/* Rich SEO Content & FAQ Section for Search Engine Rankings */}
      <section className="border-t border-zinc-800/80 bg-[#0f0f0f] py-12 px-4 sm:px-6 lg:px-8 text-zinc-400">
        <div className="max-w-7xl mx-auto space-y-8">
          <div className="space-y-3">
            <h2 className="text-xl sm:text-2xl font-black text-white tracking-wide">
              BleuStream – Premier Free Cinema & TV Streaming Platform
            </h2>
            <p className="text-xs sm:text-sm text-zinc-400 leading-relaxed max-w-4xl">
              Welcome to <strong className="text-white">BleuStream</strong>, your destination for streaming full-length movies, complete TV series seasons, and trending anime in pristine 1080p Full HD and 4K Ultra HD. Enjoy unlimited streaming with zero subscription fees, instant multi-mirror CDN playback, multi-language subtitles, and an anti-popup environment.
            </p>
          </div>

          {/* SEO Popular Keywords & Topics */}
          <div className="space-y-3">
            <h3 className="text-xs font-bold uppercase tracking-wider text-zinc-300">
              Popular Free Streaming Categories
            </h3>
            <div className="flex flex-wrap gap-2 text-xs">
              {[
                'Watch Free Movies Online',
                'Watch Action Movies HD',
                'Free TV Shows Streaming',
                'Trending Anime 2026',
                'Box Office Cinema 4K',
                'Sci-Fi Movies Online',
                'Watch Comedy Movies',
                'Horror Movies Free',
                'Top Rated IMDB Movies',
                'No Sign-Up Movie Streaming',
                'Ultra HD Cinema Players',
              ].map((tag) => (
                <span
                  key={tag}
                  className="px-2.5 py-1 bg-zinc-900/90 border border-zinc-800 rounded-lg text-zinc-300 text-[11px] font-medium hover:border-sky-500/50 transition cursor-default"
                >
                  {tag}
                </span>
              ))}
            </div>
          </div>

          {/* SEO FAQ Rich Accordion */}
          <div className="space-y-3 pt-2">
            <h3 className="text-sm font-bold uppercase tracking-wider text-white flex items-center gap-2">
              <Sparkles className="w-4 h-4 text-sky-400" />
              Frequently Asked Questions (FAQ)
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 text-xs">
              <div className="p-4 bg-zinc-900/60 border border-zinc-800 rounded-xl space-y-2">
                <h4 className="font-bold text-white">How do I watch movies on BleuStream?</h4>
                <p className="text-zinc-400 text-[11px] leading-relaxed">
                  Simply select any movie, TV show, or anime title from the catalog and click the red Play triangle. Your stream will launch instantly on high-speed CDN mirrors.
                </p>
              </div>
              <div className="p-4 bg-zinc-900/60 border border-zinc-800 rounded-xl space-y-2">
                <h4 className="font-bold text-white">What resolutions are supported?</h4>
                <p className="text-zinc-400 text-[11px] leading-relaxed">
                  BleuStream supports 720p, 1080p Full HD, and 4K Ultra HD playback with high dynamic range audio, stereo surround sound, and multiple server switches.
                </p>
              </div>
              <div className="p-4 bg-zinc-900/60 border border-zinc-800 rounded-xl space-y-2">
                <h4 className="font-bold text-white">Is there an anti-popup shield?</h4>
                <p className="text-zinc-400 text-[11px] leading-relaxed">
                  Yes, our player is protected by a strict sandbox and popup blocker to ensure an uninterrupted, clean cinema viewing experience.
                </p>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="bg-black py-8 px-4 sm:px-6 lg:px-8 text-zinc-500 text-xs border-t border-zinc-900">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-2">
            <span className="text-xl font-bebas tracking-wider text-sky-400">
              BLEU<span className="text-cyan-300">STREAM</span>
            </span>
            <span className="text-[9px] px-1.5 py-0.2 bg-zinc-800 text-zinc-400 rounded font-mono">
              v1.0 ULTRA HD
            </span>
          </div>
          <p className="text-center md:text-left text-zinc-500 text-[11px]">
            BleuStream uses TMDB v3 API for media metadata and delivers high-performance 1080p / 4K streaming through 7 high-speed mirrors.
          </p>
          <div className="flex items-center gap-4 text-zinc-400">
            <button
              onClick={() => setCurrentTab('watchlist')}
              className="hover:text-white transition cursor-pointer"
            >
              My List
            </button>
            <span>•</span>
            <button
              onClick={() => setCurrentTab('history')}
              className="hover:text-white transition cursor-pointer"
            >
              Watch History
            </button>
            <span>•</span>
            <span className="text-emerald-400 font-semibold">7 High-Speed Mirrors Online</span>
          </div>
        </div>
      </footer>

      {/* Media Detail Modal */}
      {detailMedia && (
        <MediaDetailModal
          media={detailMedia}
          onClose={() => setDetailMedia(null)}
          onPlay={(item) => handlePlayMedia(item)}
          onOpenTrailer={(item) => {
            setTrailerMedia(item);
          }}
          onToggleWatchlist={toggleWatchlist}
          isInWatchlist={watchlistIds.has(detailMedia.id)}
        />
      )}

      {/* Official YouTube Trailer Modal */}
      {trailerMedia && (
        <TrailerModal
          media={trailerMedia}
          onClose={() => setTrailerMedia(null)}
          onWatchNow={() => {
            handlePlayMedia(trailerMedia);
            setTrailerMedia(null);
            setDetailMedia(null);
          }}
        />
      )}

      {/* Settings Modal */}
      {showSettings && (
        <SettingsModal
          settings={settings}
          onSave={(newSettings) => setSettings(newSettings)}
          onClose={() => setShowSettings(false)}
          onTriggerTestLocker={handleTriggerTestLocker}
        />
      )}

      {/* Secret Military-Grade Admin Authentication Modal */}
      <AdminLoginModal
        isOpen={isAdminLoginOpen}
        onClose={() => setIsAdminLoginOpen(false)}
        onSuccess={() => {
          setIsAdminLoginOpen(false);
          setIsAdminDashboardOpen(true);
        }}
      />

      {/* Real-time Telemetry & Stream Command Center */}
      <AdminDashboard
        isOpen={isAdminDashboardOpen}
        onClose={() => setIsAdminDashboardOpen(false)}
      />

      {/* Universal In-Page Verification Locker Modal (Works for Mobile & PC) */}
      <LockerModal mediaId={activeMedia?.id} />
    </div>
  );
}

