                  <div>
                    <label className="text-zinc-400 block mb-1">Confirm New Password:</label>
                    <input
                      type="password"
                      value={confirmPw}
                      onChange={(e) => setConfirmPw(e.target.value)}
                      placeholder="Confirm new password..."
                      required
                      className="w-full bg-black/60 border border-zinc-700 rounded-xl px-3 py-2 text-white focus:outline-none focus:border-sky-500"
                    />
                  </div>
                </div>

                <div className="pt-2">
                  <button
                    type="submit"
                    className="px-5 py-2.5 bg-[#0ea5e9] hover:bg-sky-600 text-white font-bold rounded-xl transition cursor-pointer shadow-lg shadow-sky-950/40"
                  >
                    Save & Re-Hash Master Password
                  </button>
                </div>
              </form>
            </div>

            {/* Quick 4-Digit Security PIN */}
            <div className="bg-[#11131a] border border-zinc-800 rounded-2xl p-5 space-y-4 shadow-xl">
              <div className="flex items-center gap-2.5 font-mono text-white font-bold text-base border-b border-zinc-800 pb-3">
                <Shield className="w-5 h-5 text-emerald-400" />
                <span>Quick Security PIN (For Rapid Terminal Access)</span>
              </div>

              {pinSuccessMsg && (
                <div className="p-3 bg-emerald-950/80 border border-emerald-500/50 rounded-xl text-xs text-emerald-300 font-mono">
                  {pinSuccessMsg}
                </div>
              )}

              <form onSubmit={handleSetQuickPin} className="flex items-center gap-3 font-mono text-xs">
                <input
                  type="password"
                  maxLength={6}
                  value={quickPin}
                  onChange={(e) => setQuickPin(e.target.value)}
                  placeholder="e.g. 7842"
                  className="bg-black/60 border border-zinc-700 rounded-xl px-3.5 py-2 text-white focus:outline-none focus:border-sky-500 w-44 tracking-widest text-center"
                />
                <button
                  type="submit"
                  className="px-4 py-2 bg-zinc-800 hover:bg-zinc-700 text-white font-bold rounded-xl transition cursor-pointer"
                >
                  Set PIN
                </button>
              </form>
            </div>

            {/* Data Export & Backup Controls */}
            <div className="bg-[#11131a] border border-zinc-800 rounded-2xl p-5 space-y-4 shadow-xl font-mono">
              <div className="flex items-center gap-2.5 text-white font-bold text-base border-b border-zinc-800 pb-3">
                <Download className="w-5 h-5 text-blue-400" />
                <span>Export Telemetry & Stream History</span>
              </div>

              <div className="flex flex-wrap items-center gap-3">
                <button
                  type="button"
                  onClick={handleDownloadCSV}
                  className="px-4 py-2.5 bg-zinc-800 hover:bg-zinc-700 border border-zinc-700 text-white text-xs font-bold rounded-xl transition flex items-center gap-2 cursor-pointer"
                >
                  <Download className="w-4 h-4 text-emerald-400" />
                  <span>Download Telemetry CSV</span>
                </button>

                <button
                  type="button"
                  onClick={handleDownloadJSON}
                  className="px-4 py-2.5 bg-zinc-800 hover:bg-zinc-700 border border-zinc-700 text-white text-xs font-bold rounded-xl transition flex items-center gap-2 cursor-pointer"
                >
                  <Download className="w-4 h-4 text-blue-400" />
                  <span>Download Full JSON Dump</span>
                </button>

                <button
                  type="button"
                  onClick={handlePanicWipe}
                  className="px-4 py-2.5 bg-red-950/80 hover:bg-red-900 border border-red-700/60 text-red-300 text-xs font-bold rounded-xl transition flex items-center gap-2 ml-auto cursor-pointer"
                >
                  <Trash2 className="w-4 h-4 text-sky-400" />
                  <span>Panic Wipe Terminal</span>
                </button>
              </div>
            </div>

            {/* Security Audit Log */}
            <div className="bg-[#11131a] border border-zinc-800 rounded-2xl p-5 space-y-4 shadow-xl font-mono">
              <h4 className="text-sm font-bold text-white uppercase tracking-wider">
                Recent Security Audit Logs
              </h4>

              <div className="space-y-2 max-h-52 overflow-y-auto pr-1">
                {auditLogs.map((log) => (
                  <div
                    key={log.id}
                    className="p-2.5 bg-black/50 border border-zinc-850 rounded-lg flex items-center justify-between text-xs"
                  >
                    <div className="flex items-center gap-2">
                      <span
                        className={`w-2 h-2 rounded-full ${
                          log.event === 'login_success'
                            ? 'bg-emerald-400'
                            : log.event === 'login_failed'
                            ? 'bg-sky-500'
                            : 'bg-amber-400'
                        }`}
                      />
                      <span className="text-zinc-200 font-semibold">{log.event}</span>
                      <span className="text-zinc-500">• {log.details}</span>
                    </div>
                    <span className="text-zinc-500 text-[11px]">
                      {new Date(log.timestamp).toLocaleTimeString()}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

src/components/admin/AdminLoginModal.tsx:
import React, { useState, useEffect } from 'react';
import { Shield, Lock, Eye, EyeOff, AlertTriangle, Key, X, CheckCircle2 } from 'lucide-react';
import { adminAuth, AuthState } from '../../services/adminAuth';

interface AdminLoginModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}

export const AdminLoginModal: React.FC<AdminLoginModalProps> = ({
  isOpen,
  onClose,
  onSuccess,
}) => {
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [authState, setAuthState] = useState<AuthState>(adminAuth.getState());
  const [countdown, setCountdown] = useState<number | null>(null);

  useEffect(() => {
    const unsub = adminAuth.subscribe((st) => {
      setAuthState(st);
      if (st.lockoutUntil && st.lockoutUntil > Date.now()) {
        setCountdown(Math.ceil((st.lockoutUntil - Date.now()) / 1000));
      } else {
        setCountdown(null);
      }
    });
    return unsub;
  }, []);

  // Lockout countdown timer
  useEffect(() => {
    if (!countdown || countdown <= 0) return;
    const timer = setInterval(() => {
      setCountdown((prev) => {
        if (!prev || prev <= 1) {
          setErrorMsg(null);
          return null;
        }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [countdown]);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!password.trim()) return;

    setIsLoading(true);
    setErrorMsg(null);

    const result = await adminAuth.login(password.trim());
    setIsLoading(false);

    if (result.success) {
      setPassword('');
      onSuccess();
    } else {
      setErrorMsg(result.error || 'Authentication failed');
      // Shake animation effect
    }
  };

  const isLocked = countdown !== null && countdown > 0;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-3 sm:p-4 bg-black/85 backdrop-blur-xl animate-in fade-in duration-200">
      <div className="relative w-full max-w-md bg-[#0c0d10] border border-red-900/40 rounded-2xl p-6 shadow-2xl shadow-sky-950/30 space-y-6 text-white overflow-hidden">
        {/* Glowing top line */}
        <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-sky-500 via-amber-500 to-cyan-500 animate-pulse" />

        {/* Close Button */}
        <button
          type="button"
          onClick={onClose}
          className="absolute top-4 right-4 p-1.5 text-zinc-500 hover:text-white bg-zinc-900/80 hover:bg-zinc-800 rounded-lg transition cursor-pointer"
        >
          <X className="w-4 h-4" />
        </button>

        {/* Security Shield Header */}
        <div className="flex items-center gap-3.5 pt-2">
          <div className="p-3 bg-red-950/60 border border-sky-500/40 rounded-2xl text-sky-400 shadow-inner">
            <Shield className="w-7 h-7" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h2 className="text-lg font-black tracking-wider uppercase text-white font-mono">
                Security Vault
              </h2>
              <span className="px-2 py-0.5 bg-red-900/40 border border-red-700/50 text-cyan-400 text-[9px] font-black uppercase rounded tracking-widest">
                SHA-256
              </span>
            </div>
            <p className="text-xs text-zinc-400 font-mono">
              Live Cinema Stream Monitor & Telemetry Control
            </p>
          </div>
        </div>

        {/* Lockout Warning Banner if brute forced */}
        {isLocked && (
          <div className="p-3.5 bg-red-950/80 border border-sky-500 rounded-xl space-y-1 animate-in zoom-in-95">
            <div className="flex items-center gap-2 text-cyan-400 font-bold text-xs">
              <AlertTriangle className="w-4 h-4 shrink-0 text-cyan-400" />
              <span>SECURITY LOCKOUT ACTIVATED</span>
            </div>
            <p className="text-xs text-zinc-300">
              Terminal is temporarily locked due to multiple failed credentials.
            </p>
            <div className="text-sm font-mono font-black text-amber-400 pt-1">
              Cooldown remaining: {countdown}s
            </div>
          </div>
        )}

        {/* Error message */}
        {errorMsg && !isLocked && (
          <div className="p-3 bg-red-950/50 border border-red-800/80 rounded-xl text-xs text-red-300 flex items-start gap-2">
            <AlertTriangle className="w-4 h-4 shrink-0 text-cyan-400 mt-0.5" />
            <span>{errorMsg}</span>
          </div>
        )}

        {/* Login Form */}
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-1.5">
            <label className="text-xs font-semibold text-zinc-300 flex items-center justify-between">
              <span className="flex items-center gap-1.5">
                <Key className="w-3.5 h-3.5 text-zinc-400" />
                <span>Master Password / Quick PIN:</span>
              </span>
              <span className="text-[10px] text-zinc-500 font-mono">Salted Hash</span>
            </label>

            <div className="relative">
              <input
                type={showPassword ? 'text' : 'password'}
                disabled={isLocked || isLoading}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Enter master password..."
                autoFocus
                className="w-full bg-black/70 border border-zinc-800 focus:border-sky-500 disabled:opacity-50 rounded-xl px-3.5 py-2.5 text-sm text-white placeholder-zinc-600 font-mono tracking-wider focus:outline-none transition"
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-zinc-500 hover:text-zinc-300 p-1 cursor-pointer"
              >
                {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
              </button>
            </div>
          </div>

          {/* Submit button */}
          <button
            type="submit"
            disabled={isLocked || isLoading || !password.trim()}
            className="w-full py-3 bg-[#0ea5e9] hover:bg-sky-600 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold text-sm rounded-xl transition flex items-center justify-center gap-2 shadow-lg shadow-sky-950/50 cursor-pointer"
          >
            {isLoading ? (
              <span className="inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
            ) : (
              <>
                <Lock className="w-4 h-4" />
                <span>Unlock Command Center</span>
              </>
            )}
          </button>
        </form>

        {/* Security Specs Footer */}
        <div className="pt-2 border-t border-zinc-900 flex items-center justify-between text-[10px] text-zinc-500 font-mono">
          <span>Anti-Brute Force (5 attempts)</span>
          <span className="text-emerald-500 flex items-center gap-1">
            <CheckCircle2 className="w-3 h-3" />
            256-Bit Guard Active
          </span>
        </div>
      </div>
    </div>
  );
};

src/components/ArticlesHub.tsx:
import React, { useState, useEffect } from 'react';
import {
  BookOpen,
  Calendar,
  Clock,
  Star,
  Play,
  ArrowRight,
  Search,
  Sparkles,
  ChevronRight,
  Share2,
  Film,
  CheckCircle2,
  HelpCircle,
  ArrowLeft,
} from 'lucide-react';
import { SEO_ARTICLES, SEOArticle } from '../data/seoArticles';
import { MediaItem } from '../types';

interface ArticlesHubProps {
  initialSlug?: string | null;
  onPlayMediaById: (mediaId: number, type: 'movie' | 'tv', title: string) => void;
  onBackToHome: () => void;
}

export const ArticlesHub: React.FC<ArticlesHubProps> = ({
  initialSlug,
  onPlayMediaById,
  onBackToHome,
}) => {
  const [selectedArticle, setSelectedArticle] = useState<SEOArticle | null>(() => {
    if (initialSlug) {
      return SEO_ARTICLES.find((a) => a.slug === initialSlug) || null;
    }
    return null;
  });

  const [activeCategory, setActiveCategory] = useState<string>('All');
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [copied, setCopied] = useState<boolean>(false);

  useEffect(() => {
    if (initialSlug) {
      const found = SEO_ARTICLES.find((a) => a.slug === initialSlug);
      if (found) {
        setSelectedArticle(found);
      }
    }
  }, [initialSlug]);

  // Scroll to top when opening an article
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [selectedArticle]);

  const categories = [
    'All',
    'Movie Guides',
    'TV Series Guides',
    'Anime Guides',
    'Curated Recommendations',
  ];

  const filteredArticles = SEO_ARTICLES.filter((article) => {
    const matchesCategory =
      activeCategory === 'All' || article.category === activeCategory;
    const matchesSearch =
      article.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      article.excerpt.toLowerCase().includes(searchQuery.toLowerCase()) ||
      article.keywords.some((k) => k.toLowerCase().includes(searchQuery.toLowerCase()));
    return matchesCategory && matchesSearch;
  });

  const handleShare = (art: SEOArticle) => {
    const url = `https://bleustream.online/articles/${art.slug}.html`;
    if (navigator.clipboard) {
      navigator.clipboard.writeText(url);
      setCopied(true);
      setTimeout(() => setCopied(false), 2500);
    }
  };

  // Detailed Article Reader View
  if (selectedArticle) {
    return (
      <div className="min-h-screen bg-[#141414] text-white pt-24 pb-20 px-4 sm:px-6 lg:px-8">
        <div className="max-w-4xl mx-auto space-y-8">
          {/* Back & Breadcrumb Bar */}
          <div className="flex flex-wrap items-center justify-between gap-4 border-b border-zinc-800 pb-4">
            <button
              type="button"
              onClick={() => setSelectedArticle(null)}
              className="inline-flex items-center gap-2 text-sm font-semibold text-zinc-400 hover:text-white transition cursor-pointer"
            >
              <ArrowLeft className="w-4 h-4" />
              <span>Back to Cinema Articles Hub</span>
            </button>

            <div className="flex items-center gap-3">
              <button
                type="button"
                onClick={() => handleShare(selectedArticle)}
                className="px-3 py-1.5 rounded-lg bg-zinc-900 border border-zinc-800 hover:border-zinc-700 text-xs text-zinc-300 hover:text-white transition flex items-center gap-1.5 cursor-pointer"
              >
                <Share2 className="w-3.5 h-3.5" />
                <span>{copied ? 'Link Copied!' : 'Share Article'}</span>
              </button>
            </div>
          </div>

          {/* Article Header */}
          <div className="space-y-4">
            <div className="flex items-center gap-2">
              <span className="px-3 py-1 bg-sky-500/20 border border-sky-400/40 text-cyan-400 text-xs font-bold rounded-full uppercase tracking-wider">
                {selectedArticle.category}
              </span>
              <span className="px-2.5 py-1 bg-amber-950/80 border border-amber-500/40 text-amber-300 text-xs font-bold rounded-full flex items-center gap-1 font-mono">
                <Star className="w-3 h-3 fill-amber-400 text-amber-400" />
                <span>{selectedArticle.rating}</span>
              </span>
            </div>

            <h1 className="text-2xl sm:text-4xl lg:text-5xl font-black text-white leading-tight">
              {selectedArticle.title}
            </h1>

            <div className="flex flex-wrap items-center gap-4 text-xs text-zinc-400 font-medium">
              <span className="text-zinc-200">
                By <strong>{selectedArticle.author}</strong> ({selectedArticle.authorRole})
              </span>
              <span>•</span>
              <span className="flex items-center gap-1">
                <Calendar className="w-3.5 h-3.5 text-zinc-500" />
                <span>{selectedArticle.publishedDate}</span>
              </span>
              <span>•</span>
              <span className="flex items-center gap-1">
                <Clock className="w-3.5 h-3.5 text-zinc-500" />
                <span>{selectedArticle.readTime}</span>
              </span>
            </div>
          </div>

          {/* Cover Hero Banner with Direct Play Overlay */}
          <div className="relative rounded-2xl overflow-hidden border border-zinc-800 shadow-2xl group">
            <img
              src={selectedArticle.coverImage}
              alt={selectedArticle.title}
              className="w-full h-64 sm:h-96 object-cover transform group-hover:scale-105 transition-transform duration-500"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-black via-black/40 to-transparent flex items-end p-6 sm:p-8">
              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 w-full">
                <div>
                  <h3 className="text-lg sm:text-xl font-bold text-white drop-shadow">
                    Stream {selectedArticle.relatedMediaTitle} in Ultra HD
                  </h3>
                  <p className="text-xs text-zinc-300 drop-shadow">
                    Instant 1080p/4K playback on BleuStream with 0 buffering.
                  </p>
                </div>
                <button
                  type="button"
                  onClick={() =>
                    onPlayMediaById(
                      selectedArticle.relatedMediaId,
                      selectedArticle.relatedMediaType,
                      selectedArticle.relatedMediaTitle
                    )
                  }
                  className="px-6 py-3 bg-[#0ea5e9] hover:bg-sky-600 text-white font-extrabold rounded-xl text-sm transition shadow-lg shadow-sky-950/60 flex items-center justify-center gap-2 cursor-pointer shrink-0 active:scale-95"
                >
                  <Play className="w-4 h-4 fill-white" />
                  <span>Watch Free Now</span>
                </button>
              </div>
            </div>
          </div>

          {/* Excerpt Lead */}
          <div className="p-5 rounded-2xl bg-zinc-900/60 border-l-4 border-sky-500 text-zinc-300 text-base sm:text-lg leading-relaxed font-serif italic">
            "{selectedArticle.excerpt}"
          </div>

          {/* Content Sections */}
          <div className="space-y-8 text-zinc-300 leading-relaxed text-sm sm:text-base">
            {selectedArticle.sections.map((section, idx) => (
              <div
                key={idx}
                className="space-y-4 p-6 bg-zinc-900/40 border border-zinc-800/80 rounded-2xl"
              >
                <h2 className="text-xl sm:text-2xl font-black text-white flex items-center gap-2">
                  <Film className="w-5 h-5 text-sky-400 shrink-0" />
                  <span>{section.heading}</span>
                </h2>
                {section.subheading && (
                  <h3 className="text-base font-bold text-zinc-200">{section.subheading}</h3>
                )}
                {section.paragraphs.map((p, pIdx) => (
                  <p key={pIdx} className="text-zinc-300">
                    {p}
                  </p>
                ))}
                {section.bulletPoints && (
                  <ul className="space-y-2 pt-2">
                    {section.bulletPoints.map((point, bIdx) => (
                      <li key={bIdx} className="flex items-start gap-2.5 text-xs sm:text-sm text-zinc-300">
                        <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0 mt-0.5" />
                        <span>{point}</span>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            ))}
          </div>

          {/* FAQ Accordions for Google Snippets & Engagement */}
          {selectedArticle.faqs.length > 0 && (
            <div className="space-y-4 pt-4">
              <h2 className="text-xl sm:text-2xl font-black text-white flex items-center gap-2">
                <HelpCircle className="w-5 h-5 text-amber-400" />
                <span>Frequently Asked Questions</span>
              </h2>
              <div className="space-y-3">
                {selectedArticle.faqs.map((faq, idx) => (
                  <div
                    key={idx}
                    className="p-5 bg-zinc-900/70 border border-zinc-800 rounded-xl space-y-2"
                  >
                    <h3 className="text-sm sm:text-base font-bold text-white flex items-center gap-2">
                      <span className="w-5 h-5 rounded-full bg-sky-500/20 text-sky-400 text-xs flex items-center justify-center font-mono">
                        Q
                      </span>
                      <span>{faq.question}</span>
                    </h3>
                    <p className="text-xs sm:text-sm text-zinc-400 pl-7 leading-relaxed">
                      {faq.answer}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Bottom Stream Call-To-Action */}
          <div className="p-8 rounded-2xl bg-gradient-to-r from-red-950/60 via-zinc-900 to-black border border-sky-400/40 text-center space-y-4 shadow-xl">
            <Sparkles className="w-8 h-8 text-amber-400 mx-auto" />
            <h3 className="text-2xl font-black text-white">
              Watch {selectedArticle.relatedMediaTitle} Full Movie on BleuStream
            </h3>
            <p className="text-xs sm:text-sm text-zinc-400 max-w-md mx-auto">
              Choose from 7 verified fast mirrors including VidSrc Cloud and enjoy unrestricted 4K Ultra HD cinema.
            </p>
            <button
              type="button"
              onClick={() =>
                onPlayMediaById(
                  selectedArticle.relatedMediaId,
                  selectedArticle.relatedMediaType,
                  selectedArticle.relatedMediaTitle
                )
              }
              className="px-8 py-3.5 bg-gradient-to-r from-sky-500 to-amber-600 hover:from-red-500 hover:to-amber-500 text-white font-extrabold rounded-xl text-base transition shadow-xl shadow-sky-950/80 inline-flex items-center gap-2 cursor-pointer active:scale-95"
            >
              <Play className="w-5 h-5 fill-white" />
              <span>Launch Video Player</span>
            </button>
          </div>

          {/* More Articles Preview */}
          <div className="space-y-4 pt-8 border-t border-zinc-800">
            <h3 className="text-lg font-bold text-white">More Cinema Guides You Might Like</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
              {SEO_ARTICLES.filter((a) => a.id !== selectedArticle.id)
                .slice(0, 3)
                .map((art) => (
                  <div
                    key={art.id}
                    onClick={() => setSelectedArticle(art)}
                    className="p-3 bg-zinc-900/60 border border-zinc-800 hover:border-zinc-700 rounded-xl cursor-pointer transition group"
                  >
                    <img
                      src={art.coverImage}
                      alt={art.title}
                      className="w-full h-32 object-cover rounded-lg mb-2"
                    />
                    <span className="text-[10px] text-cyan-400 font-bold uppercase tracking-wider block mb-1">
                      {art.category}
                    </span>
                    <h4 className="text-xs font-bold text-white group-hover:text-red-300 line-clamp-2 leading-snug">
                      {art.title}
                    </h4>
                    <span className="text-[10px] text-zinc-500 mt-2 block font-mono">
                      {art.readTime} • {art.rating}
                    </span>
                  </div>
                ))}
            </div>
          </div>
        </div>
      </div>
    );
  }

  // Articles Hub Directory View
  return (
    <div className="min-h-screen bg-[#141414] text-white pt-24 pb-20 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto space-y-8">
        {/* Hub Header */}
        <div className="text-center space-y-3 max-w-2xl mx-auto">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-sky-500/10 border border-sky-400/30 text-cyan-400 text-xs font-bold uppercase tracking-wider">
            <BookOpen className="w-3.5 h-3.5" />
            <span>BleuStream Cinema Editorial & SEO Guides</span>
          </div>
          <h1 className="text-3xl sm:text-5xl font-black font-bebas tracking-wide text-white">
            Cinema Guides, Reviews & Streaming Tips
          </h1>
          <p className="text-xs sm:text-sm text-zinc-400 leading-relaxed">
            In-depth guides, release countdowns, ending breakdowns, and streaming recommendations for the biggest blockbusters and anime series.
          </p>
        </div>

        {/* Search & Categories Bar */}
        <div className="flex flex-col md:flex-row items-center justify-between gap-4 bg-zinc-900/60 border border-zinc-800 p-4 rounded-2xl shadow-xl">
          {/* Categories */}
          <div className="flex items-center gap-2 overflow-x-auto w-full md:w-auto no-scrollbar py-1">
            {categories.map((cat) => (
              <button
                key={cat}
                type="button"
                onClick={() => setActiveCategory(cat)}
                className={`px-3.5 py-1.5 rounded-xl text-xs font-bold whitespace-nowrap transition cursor-pointer ${
                  activeCategory === cat
                    ? 'bg-sky-500 text-white shadow-md shadow-sky-950/40'
                    : 'bg-zinc-800/80 text-zinc-400 hover:text-white hover:bg-zinc-800'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>

          {/* Search Box */}
          <div className="relative w-full md:w-72">
            <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search guides, movies..."
              className="w-full bg-black/60 border border-zinc-700 rounded-xl pl-9 pr-4 py-2 text-xs text-white focus:outline-none focus:border-sky-400"
            />
          </div>
        </div>

        {/* Articles Grid */}
        {filteredArticles.length === 0 ? (
          <div className="text-center py-16 bg-zinc-900/30 rounded-2xl border border-zinc-800 space-y-3">
            <BookOpen className="w-10 h-10 text-zinc-600 mx-auto" />
            <h3 className="text-base font-bold text-zinc-300">No articles match your query</h3>
            <p className="text-xs text-zinc-500">Try changing your search terms or category filter.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredArticles.map((art) => (
              <article
                key={art.id}
                className="bg-[#18181b] border border-zinc-800 hover:border-zinc-700 rounded-2xl overflow-hidden flex flex-col justify-between transition-all duration-300 hover:-translate-y-1 shadow-xl group"
              >
                <div>
                  {/* Poster Thumbnail */}
                  <div
                    onClick={() => setSelectedArticle(art)}
                    className="relative h-48 overflow-hidden cursor-pointer"
                  >
                    <img
                      src={art.coverImage}
                      alt={art.title}
                      loading="lazy"
                      className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                    />
                    <div className="absolute top-3 left-3 flex items-center gap-1.5">
                      <span className="px-2.5 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider bg-black/70 backdrop-blur border border-zinc-700 text-white">
                        {art.category}
                      </span>
                    </div>
                    <div className="absolute top-3 right-3">
                      <span className="px-2 py-0.5 rounded-full text-[10px] font-mono font-bold bg-amber-950/80 border border-amber-500/40 text-amber-300 flex items-center gap-1">
                        <Star className="w-2.5 h-2.5 fill-amber-400 text-amber-400" />
                        <span>{art.rating}</span>
                      </span>
                    </div>
                  </div>

                  {/* Body Content */}
                  <div className="p-5 space-y-3">
                    <div className="flex items-center gap-2 text-[11px] text-zinc-500 font-mono">
                      <span>{art.publishedDate}</span>
                      <span>•</span>
                      <span>{art.readTime}</span>
                    </div>

                    <h2
                      onClick={() => setSelectedArticle(art)}
                      className="text-base font-bold text-white group-hover:text-cyan-400 transition cursor-pointer line-clamp-2 leading-snug"
                    >
                      {art.title}
                    </h2>

                    <p className="text-xs text-zinc-400 line-clamp-3 leading-relaxed">
                      {art.excerpt}
                    </p>
                  </div>
                </div>

                {/* Card Footer Actions */}
                <div className="p-5 pt-0 flex items-center justify-between gap-3 border-t border-zinc-800/80 mt-4">
                  <button
                    type="button"
                    onClick={() => setSelectedArticle(art)}
                    className="text-xs font-bold text-zinc-300 hover:text-white flex items-center gap-1 transition cursor-pointer"
                  >
                    <span>Read Guide</span>
                    <ChevronRight className="w-3.5 h-3.5 text-sky-400" />
                  </button>

                  <button
                    type="button"
                    onClick={() =>
                      onPlayMediaById(art.relatedMediaId, art.relatedMediaType, art.relatedMediaTitle)
                    }
                    className="px-3.5 py-1.5 bg-sky-500/20 hover:bg-sky-500 border border-sky-400/40 hover:border-sky-500 text-red-300 hover:text-white rounded-xl text-xs font-bold transition flex items-center gap-1.5 cursor-pointer"
                  >
                    <Play className="w-3 h-3 fill-current" />
                    <span>Watch Movie</span>
                  </button>
                </div>
              </article>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

src/components/CinemaPlayer.tsx:
import React, { useState, useEffect, useRef } from 'react';
import {
  ArrowLeft,
  RefreshCw,
  Maximize2,
  Tv,
  Film,
  Star,
  Clock,
  Calendar,
  Layers,
  ChevronLeft,
  ChevronRight,
  ShieldCheck,
  CheckCircle2,
  ListVideo,
  Play,
  Lock,
  AlertCircle,
  Users,
  ExternalLink,
} from 'lucide-react';
import { MediaItem, TVEpisode, CastMember, SeasonSummary } from '../types';
import { STREAMING_SERVERS } from '../config/servers';
import { fetchTVSeason, fetchTVDetails, fetchDetails, fetchCredits, fetchSimilar, getPosterUrl, getBackdropUrl } from '../services/tmdb';
import { triggerActiveLocker, triggerNativeOGAdsLocker, subscribeToLockerUnlock, markMediaUnlocked } from '../utils/locker';
import { useLanguage } from '../context/LanguageContext';
import { WatchPartyModal } from './WatchPartyModal';
import { CommunityReviews } from './CommunityReviews';
import { liveTracker } from '../services/liveTracker';
import { lockerConfig, LockerConfig } from '../services/lockerConfig';

interface CinemaPlayerProps {
  media: MediaItem;
  initialSeason?: number;
  initialEpisode?: number;
  onBack: () => void;
  onSelectSimilar: (item: MediaItem) => void;
  onStreamStarted: () => void;
  isLocked?: boolean;
  onTriggerLocker?: () => void;
}

export const CinemaPlayer: React.FC<CinemaPlayerProps> = ({
  media,
  initialSeason = 1,
  initialEpisode = 1,
  onBack,
  onSelectSimilar,
  onStreamStarted,
  isLocked = false,
  onTriggerLocker,
}) => {
  const { t } = useLanguage();
  const isTv = media.media_type === 'tv' || !!media.first_air_date;
  const title = media.title || media.name || 'Now Streaming';
  const [lockerCfg, setLockerCfg] = useState<LockerConfig>(lockerConfig.getConfig());
  const lockerDelaySeconds = lockerCfg.delaySeconds || 15;
  const isLockerEnabled = lockerCfg.enabled;

  const [selectedServer, setSelectedServer] = useState(STREAMING_SERVERS[0]);
  const [currentSeason, setCurrentSeason] = useState(initialSeason);
  const [currentEpisode, setCurrentEpisode] = useState(initialEpisode);
  const [availableSeasons, setAvailableSeasons] = useState<SeasonSummary[]>(media.seasons || []);
  const [totalSeasonsCount, setTotalSeasonsCount] = useState<number>(media.number_of_seasons || 1);
  const [episodes, setEpisodes] = useState<TVEpisode[]>([]);
  const [loadingEpisodes, setLoadingEpisodes] = useState(false);
  const [cast, setCast] = useState<CastMember[]>([]);
  const [similar, setSimilar] = useState<MediaItem[]>([]);
  const [iframeKey, setIframeKey] = useState(0);
  const [isCinemaExpanded, setIsCinemaExpanded] = useState(false);
  const [showEpisodeDrawer, setShowEpisodeDrawer] = useState(false);
  const [isPlayerLoading, setIsPlayerLoading] = useState(false);
  const [imdbId, setImdbId] = useState<string | undefined>(media.imdb_id);
  const [hasStartedPlayback, setHasStartedPlayback] = useState(false);
  const [isAdBlockEnabled, setIsAdBlockEnabled] = useState(true);

  // Suppress popup advertisements when Ad-Shield is enabled
  useEffect(() => {
    if (!isAdBlockEnabled) return;
    const originalOpen = window.open;
    window.open = function (...args) {
      console.warn('Popup advertisement blocked by Ad-Shield', args);
      return null;
    };
    return () => {
      window.open = originalOpen;
    };
  }, [isAdBlockEnabled]);
  const [isLockedInternal, setIsLockedInternal] = useState(false);
  const [countdownSeconds, setCountdownSeconds] = useState(lockerDelaySeconds);
  const [isCountingDown, setIsCountingDown] = useState(false);
  const [showWatchPartyModal, setShowWatchPartyModal] = useState(false);

  // Sync with lockerConfig updates in real-time
  useEffect(() => {
    const unsub = lockerConfig.subscribe((cfg) => {
      setLockerCfg(cfg);
      setCountdownSeconds(cfg.delaySeconds);
    });
    return unsub;
  }, []);

  const effectiveLocked = isLocked || isLockedInternal;

  const isAlreadyUnlocked = () => {
    try {
      return sessionStorage.getItem(`unlocked_${media.id}`) === 'true';
    } catch {
      return false;
    }
  };

  // Reset playback and countdown whenever a new media is chosen
  useEffect(() => {
    setHasStartedPlayback(false);
    setIsLockedInternal(false);
    setIsCountingDown(false);
    setCountdownSeconds(lockerDelaySeconds);
    setIsPlayerLoading(false);

    return () => {
      liveTracker.setWatchingState(false);
    };
  }, [media.id, lockerDelaySeconds]);

  const [isUnlockedThisStream, setIsUnlockedThisStream] = useState(false);

  // Sync prop unlock: when unlocked, resume playback smoothly
  useEffect(() => {
    if (!isLocked && isUnlockedThisStream) {
      setIsLockedInternal(false);
      setIsCountingDown(false);
      setHasStartedPlayback(true);
      setIsPlayerLoading(false);
    }
  }, [isLocked, isUnlockedThisStream]);

  // Auto-resume when OGAds completion event or callback is fired
  useEffect(() => {
    const unsubscribe = subscribeToLockerUnlock(() => {
      markMediaUnlocked(media.id);
      liveTracker.recordLockerEvent(media, 'unlocked');
      setIsUnlockedThisStream(true);
      setIsLockedInternal(false);
      setIsCountingDown(false);
      setHasStartedPlayback(true);
      setIsPlayerLoading(false);
    });
    return unsubscribe;
  }, [media.id]);

  // Start Countdown: ONLY starts if user has initiated playback AND locker is enabled AND not yet unlocked
  useEffect(() => {
    // Strictly do nothing if playback has NOT started yet or locker is disabled in Admin Panel!
    if (!hasStartedPlayback || !isLockerEnabled) {
      setIsCountingDown(false);
      return;
    }

    if (effectiveLocked || isUnlockedThisStream) {
      setIsCountingDown(false);
      return;
    }

    if (!isCountingDown && countdownSeconds === lockerDelaySeconds) {
      // Exactly 1 second after playback begins:
      const delayTimer = setTimeout(() => {
        setIsCountingDown(true);
      }, 1000);
      return () => clearTimeout(delayTimer);
    }
  }, [hasStartedPlayback, isLockerEnabled, effectiveLocked, isCountingDown, countdownSeconds, lockerDelaySeconds, isUnlockedThisStream]);

  // 20-Second Countdown Timer: ticks 20s silently while user is watching, then halts playback & triggers LAST();
  useEffect(() => {
    if (!isCountingDown || effectiveLocked) return;

    const interval = setInterval(() => {
      setCountdownSeconds((prev) => {
        if (prev <= 1) {
          clearInterval(interval);
          setIsCountingDown(false);
          // Playback finished delay seconds: stop movie & trigger active locker
          setIsLockedInternal(true);
          liveTracker.recordLockerEvent(media, 'prompted');
          triggerActiveLocker();
          if (onTriggerLocker) {
            onTriggerLocker();
          }
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [isCountingDown, effectiveLocked, onTriggerLocker, media]);

  // Center Play triangle button click handler ("daak lmotalat bach ibda l fraja")
  const handleStartPlayCenter = () => {
    const cfg = lockerConfig.get();

    // Check if content locker is enabled and configured to trigger on play click (▶ triangle)
    if (isLockerEnabled && !isAlreadyUnlocked() && cfg.triggerOnPlay) {
      liveTracker.recordStreamStart(media, currentSeason, currentEpisode, selectedServer.name);
      liveTracker.recordLockerEvent(media, 'prompted');
      setIsLockedInternal(true);
      triggerActiveLocker();
      if (onTriggerLocker) {
        onTriggerLocker();
      }
      return;
    }

    setHasStartedPlayback(true);
    setIsPlayerLoading(true);
    liveTracker.recordStreamStart(media, currentSeason, currentEpisode, selectedServer.name);
    liveTracker.setWatchingState(true, title);

    // Fast loading safety timeout: dismiss loading indicator in 800ms so it NEVER freezes or hangs
    setTimeout(() => {
      setIsPlayerLoading(false);
    }, 800);

    if (isAlreadyUnlocked()) {
      setIsCountingDown(false);
      setIsLockedInternal(false);
      onStreamStarted();
      return;
    }

    setIsLockedInternal(false);
    onStreamStarted();
  };

  // Advanced SEO Dynamic Optimization (Title, Meta, OpenGraph, Twitter, and Schema.org JSON-LD)
  useEffect(() => {
    const year = (media.release_date || media.first_air_date || '').slice(0, 4);
    const mediaTypeStr = isTv ? 'TV Series' : 'Movie';
    const seoTitle = `${title} ${year ? `(${year})` : ''} – Watch Free in Ultra HD on BleuStream`;
    const seoDesc = media.overview
      ? `Stream ${title} (${year}) online in full 1080p / 4K Ultra HD on BleuStream. ${media.overview.slice(0, 120)}... 7 fast mirrors, stereo sound, no buffering.`
      : `Stream ${title} for free in Ultra HD on BleuStream. Unlimited high-speed mirrors, complete episodes, and zero ads interruption.`;
    const posterFull = getPosterUrl(media.poster_path, 'w500');

    document.title = seoTitle;

    // Standard Meta
    const metaDesc = document.querySelector('meta[name="description"]');
    if (metaDesc) metaDesc.setAttribute('content', seoDesc);

    // OpenGraph
    const ogTitle = document.querySelector('meta[property="og:title"]');
    if (ogTitle) ogTitle.setAttribute('content', seoTitle);
    const ogDesc = document.querySelector('meta[property="og:description"]');
    if (ogDesc) ogDesc.setAttribute('content', seoDesc);
    const ogImage = document.querySelector('meta[property="og:image"]');
    if (ogImage && posterFull) ogImage.setAttribute('content', posterFull);

    // Twitter
    const twTitle = document.querySelector('meta[name="twitter:title"]');
    if (twTitle) twTitle.setAttribute('content', seoTitle);
    const twDesc = document.querySelector('meta[name="twitter:description"]');
    if (twDesc) twDesc.setAttribute('content', seoDesc);
    const twImage = document.querySelector('meta[name="twitter:image"]');
    if (twImage && posterFull) twImage.setAttribute('content', posterFull);

    // Dynamic Schema.org JSON-LD structured data for Google Rich Snippets
    let scriptEl = document.getElementById('media-jsonld') as HTMLScriptElement | null;
    if (!scriptEl) {
      scriptEl = document.createElement('script');
      scriptEl.id = 'media-jsonld';
      scriptEl.type = 'application/ld+json';
      document.head.appendChild(scriptEl);
    }

    const schemaData = {
      '@context': 'https://schema.org',
      '@type': isTv ? 'TVSeries' : 'Movie',
      name: title,
      description: media.overview || `Watch ${title} on BleuStream`,
      image: posterFull,
      datePublished: media.release_date || media.first_air_date,
      aggregateRating: {
        '@type': 'AggregateRating',
        ratingValue: (media.vote_average || 8.0).toFixed(1),
        bestRating: '10',
        worstRating: '1',
        ratingCount: Math.max(media.vote_count || 150, 100),
      },
      offers: {
        '@type': 'Offer',
        price: '0',
        priceCurrency: 'USD',
        availability: 'https://schema.org/InStock',
      },
    };
    scriptEl.textContent = JSON.stringify(schemaData);

    return () => {
      document.title = 'BleuStream – Watch Free Movies, TV Shows & Anime in Ultra HD';
      const dynamicScript = document.getElementById('media-jsonld');
      if (dynamicScript) dynamicScript.remove();
    };
  }, [title, media, isTv]);

  // Fetch full details to get imdb_id if not present
  useEffect(() => {
    if (!imdbId && media.id) {
      if (isTv) {
        fetchTVDetails(media.id).then((details) => {
          if (details?.imdb_id) setImdbId(details.imdb_id);
        });
      } else {
        fetchDetails('movie', media.id).then((details) => {
          if (details?.imdb_id) setImdbId(details.imdb_id);
        });
      }
    }
  }, [media.id, isTv, imdbId]);

  const playerContainerRef = useRef<HTMLDivElement>(null);

  const totalSeasons = Math.max(
    totalSeasonsCount,
    availableSeasons.length,
    media.number_of_seasons || 1
  );

  // Fetch full TV details to get all real seasons
  useEffect(() => {
    if (isTv) {
      fetchTVDetails(media.id).then((details) => {
        if (details) {
          if (details.number_of_seasons) {
            setTotalSeasonsCount(details.number_of_seasons);
          }
          if (details.seasons && details.seasons.length > 0) {
            const regular = details.seasons.filter((s) => s.season_number > 0);
            setAvailableSeasons(regular.length > 0 ? regular : details.seasons);
            if (regular.length > 0) {
              setTotalSeasonsCount(Math.max(...regular.map((s) => s.season_number)));
            }
          }
        }
      });
    }
  }, [media.id, isTv]);

  // Scroll smoothly to top of player when media or episode changes
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [media.id, currentSeason, currentEpisode]);

  // Reset loading state whenever server or episode changes (only if playing)
  useEffect(() => {
    if (!hasStartedPlayback) return;
    setIsPlayerLoading(true);
    const timer = setTimeout(() => {
      setIsPlayerLoading(false);
    }, 800);
    return () => clearTimeout(timer);
  }, [selectedServer.id, currentSeason, currentEpisode, iframeKey, hasStartedPlayback]);

  // Fetch TV Episodes when season changes
  useEffect(() => {
    if (isTv) {
      setLoadingEpisodes(true);
      fetchTVSeason(media.id, currentSeason).then((seasonData) => {
        if (seasonData && seasonData.episodes) {
          setEpisodes(seasonData.episodes);
        }
        setLoadingEpisodes(false);
      });
    }
  }, [media.id, isTv, currentSeason]);

  // Fetch cast and similar recommendations
  useEffect(() => {
    const type = isTv ? 'tv' : 'movie';
    fetchCredits(type, media.id).then(setCast);
    fetchSimilar(type, media.id).then(setSimilar);
  }, [media.id, isTv]);

  const activeStreamUrl = selectedServer.getUrl(
    isTv ? 'tv' : 'movie',
    media.id,
    currentSeason,
    currentEpisode,
    imdbId || media.imdb_id
  );

  const handleReloadPlayer = () => {
    setIframeKey((prev) => prev + 1);
  };

  const handleFullscreen = () => {
    if (playerContainerRef.current) {
      if (!document.fullscreenElement) {
        playerContainerRef.current.requestFullscreen?.().catch((err) => {
          console.warn('Fullscreen error:', err);
        });
      } else {
        document.exitFullscreen?.().catch(console.warn);
      }
    }
  };

  const handleNextEpisode = () => {
    if (currentEpisode < episodes.length) {
      setCurrentEpisode(currentEpisode + 1);
    } else if (currentSeason < totalSeasons) {
      setCurrentSeason(currentSeason + 1);
      setCurrentEpisode(1);
    }
  };

  const handlePrevEpisode = () => {
    if (currentEpisode > 1) {
      setCurrentEpisode(currentEpisode - 1);
    }
  };

  return (
    <div className="min-h-screen bg-[#141414] text-white pt-18 sm:pt-20 pb-16 animate-fade-in">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 space-y-5">
        {/* Navigation & Status Breadcrumb */}
        <div className="flex flex-wrap items-center justify-between gap-3 text-xs">
          <button
            type="button"
            onClick={onBack}
            className="flex items-center gap-2 px-3 py-1.5 bg-zinc-800/90 hover:bg-zinc-700 text-zinc-200 hover:text-white rounded-lg transition font-medium cursor-pointer"
          >
            <ArrowLeft className="w-4 h-4" />
            <span>{t('back_to_browse')}</span>
          </button>

          <div className="flex items-center gap-2.5">
            <span className="hidden sm:flex items-center gap-1.5 text-emerald-400 font-medium bg-emerald-950/60 border border-emerald-500/30 px-2.5 py-1 rounded-full text-xs">
              <span className="w-2 h-2 rounded-full bg-emerald-400 animate-ping" />
              <span>{t('free_hd_stream')}</span>
            </span>

            {/* In-Site Theater Mode Toggle */}
            <button
              type="button"
              onClick={() => setIsCinemaExpanded(!isCinemaExpanded)}
              className="flex items-center gap-1.5 px-3 py-1.5 bg-zinc-800 hover:bg-zinc-700 text-zinc-200 hover:text-white rounded-lg transition font-medium text-xs cursor-pointer"
            >
              <Maximize2 className="w-3.5 h-3.5" />
              <span>{isCinemaExpanded ? t('standard_view') : t('theater_mode')}</span>
            </button>

            {/* Watch Party & Share Button */}
            <button
              type="button"
              onClick={() => setShowWatchPartyModal(true)}
              className="flex items-center gap-1.5 px-3 py-1.5 bg-[#0ea5e9] hover:bg-sky-600 text-white rounded-lg transition font-bold text-xs cursor-pointer shadow-md shadow-sky-950/40"
            >
              <Users className="w-3.5 h-3.5" />
              <span>Watch Party</span>
            </button>
          </div>
        </div>

        {/* Server Selector Switch Bar */}
        <div className="bg-[#1a1a1a] border border-zinc-800 rounded-2xl p-2.5 sm:p-3 shadow-xl">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2.5 pb-2.5 border-b border-zinc-800/80">
            <div className="flex items-center gap-2">
              <div className="w-2.5 h-2.5 rounded-full bg-emerald-500 shadow-sm shadow-emerald-500/50" />
              <span className="text-xs font-bold uppercase tracking-wider text-zinc-200">
                Streaming Mirrors (VidSrc Ultra HD):
              </span>
            </div>
            <div className="flex items-center gap-2 text-[11px] text-zinc-400">
              <span className="text-emerald-400 font-medium">Verified Working • Instant Playback</span>
              <span className="hidden md:inline text-zinc-600">•</span>
              <span className="hidden md:inline">VidSrc Fast Cloud CDN with 0% buffering & Anti-Ad Shield</span>
            </div>
          </div>

          <div className="grid grid-cols-4 gap-1.5 sm:gap-2.5 pt-2">
            {STREAMING_SERVERS.map((server, idx) => {
              const isSelected = selectedServer.id === server.id;
              return (
                <button
                  key={server.id}
                  onClick={() => {
                    setSelectedServer(server);
                    liveTracker.recordStreamStart(media, currentSeason, currentEpisode, server.name);
                    handleReloadPlayer();
                  }}
                  className={`relative flex flex-col items-center sm:items-start p-1.5 sm:p-2.5 rounded-lg sm:rounded-xl border text-center sm:text-left transition-all duration-150 cursor-pointer group select-none ${
                    isSelected
                      ? 'bg-gradient-to-br from-sky-500/30 via-red-900/20 to-black border-sky-400 shadow-md shadow-sky-950/60 ring-1 sm:ring-2 ring-sky-400/40'
                      : 'bg-zinc-900/90 border-zinc-800 hover:border-zinc-700 hover:bg-zinc-800/80'
                  }`}
                >
                  <div className="w-full flex items-center justify-center sm:justify-between mb-0.5">
                    <div className="flex items-center gap-1">
                      <span className={`w-1.5 h-1.5 rounded-full ${isSelected ? 'bg-sky-500 animate-pulse' : 'bg-zinc-600'}`} />
                      <span className={`text-[10px] sm:text-xs font-black tracking-tight ${isSelected ? 'text-white' : 'text-zinc-300 group-hover:text-white'}`}>
                        VidSrc {idx + 1}
                      </span>
                    </div>
                    <span
                      className={`hidden sm:inline text-[9px] px-1.5 py-0.2 rounded-full font-bold uppercase tracking-wider ${
                        isSelected ? 'bg-sky-500 text-white shadow-sm' : 'bg-zinc-800 text-zinc-400 group-hover:bg-zinc-700'
                      }`}
                    >
                      {server.badge}
                    </span>
                  </div>
                  <div className="flex items-center justify-center sm:justify-between w-full">
                    <span className="text-[9px] sm:text-[10px] text-zinc-400 font-medium truncate">
                      <span className="sm:hidden text-[8px] font-bold text-amber-400/90">{server.badge} • </span>
                      {server.speed}
                    </span>
                  </div>
                </button>
              );
            })}
          </div>
        </div>

        {/* TV Series Season & Episode Controls (if TV series) */}
        {isTv && (
          <div className="bg-[#181818] border border-zinc-800 rounded-2xl p-4 flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
            <div className="flex items-center gap-3 w-full md:w-auto">
              <div className="p-2 bg-sky-500/20 text-sky-400 rounded-xl">
                <Tv className="w-5 h-5" />
              </div>
              <div>
                <h3 className="text-sm font-bold text-white">
                  Season {currentSeason}, Episode {currentEpisode}
                </h3>
                <p className="text-xs text-zinc-400">
                  {episodes.find((e) => e.episode_number === currentEpisode)?.name ||
                    `Episode ${currentEpisode}`}
                </p>
              </div>
            </div>

            <div className="flex flex-wrap items-center gap-2.5 w-full md:w-auto">
              {/* Season Select */}
              <div className="flex items-center gap-1.5 bg-black/60 border border-zinc-700 rounded-xl px-3 py-1.5">
                <span className="text-xs text-zinc-400 font-medium">Season:</span>
                <select
                  value={currentSeason}
                  onChange={(e) => {
                    setCurrentSeason(Number(e.target.value));
                    setCurrentEpisode(1);
                  }}
                  className="bg-transparent text-xs font-bold text-white outline-none cursor-pointer"
                >
                  {availableSeasons.length > 0 ? (
                    availableSeasons.map((s) => (
                      <option key={s.season_number} value={s.season_number} className="bg-zinc-900 text-white">
                        {s.name || `Season ${s.season_number}`} {s.episode_count ? `(${s.episode_count} eps)` : ''}
                      </option>
                    ))
                  ) : (
                    Array.from({ length: totalSeasons }, (_, i) => i + 1).map((s) => (
                      <option key={s} value={s} className="bg-zinc-900 text-white">
                        Season {s}
                      </option>
                    ))
                  )}
                </select>
              </div>

              {/* Episode Select */}
              <div className="flex items-center gap-1.5 bg-black/60 border border-zinc-700 rounded-xl px-3 py-1.5">
                <span className="text-xs text-zinc-400 font-medium">Episode:</span>
                <select
                  value={currentEpisode}
                  onChange={(e) => setCurrentEpisode(Number(e.target.value))}
                  className="bg-transparent text-xs font-bold text-white outline-none cursor-pointer"
                >
                  {episodes.length > 0 ? (
                    episodes.map((ep) => (
                      <option key={ep.id} value={ep.episode_number} className="bg-zinc-900 text-white">
                        Ep {ep.episode_number}: {ep.name.slice(0, 24)}
                      </option>
                    ))
                  ) : (
                    <option value={1} className="bg-zinc-900 text-white">
                      Episode 1
                    </option>
                  )}
                </select>
              </div>

              {/* Prev / Next Ep */}
              <div className="flex items-center gap-1">
                <button
                  type="button"
                  onClick={handlePrevEpisode}
                  disabled={currentEpisode <= 1}
                  className="p-2 bg-zinc-800 hover:bg-zinc-700 disabled:opacity-40 rounded-xl text-xs text-zinc-200 transition cursor-pointer"
                  title="Previous Episode"
                >
                  <ChevronLeft className="w-4 h-4" />
                </button>
                <button
                  type="button"
                  onClick={handleNextEpisode}
                  className="px-3 py-2 bg-zinc-800 hover:bg-zinc-700 rounded-xl text-xs font-semibold text-zinc-200 flex items-center gap-1 transition cursor-pointer"
                  title="Next Episode"
                >
                  <span>Next Ep</span>
                  <ChevronRight className="w-4 h-4" />
                </button>
              </div>

              {/* Episode Grid Toggle */}
              <button
                type="button"
                onClick={() => setShowEpisodeDrawer(!showEpisodeDrawer)}
                className={`px-3 py-2 rounded-xl text-xs font-medium flex items-center gap-1.5 transition cursor-pointer ${
                  showEpisodeDrawer
                    ? 'bg-[#0ea5e9] text-white'
                    : 'bg-zinc-800 hover:bg-zinc-700 text-zinc-300'
                }`}
              >
                <ListVideo className="w-3.5 h-3.5" />
                <span>All Seasons & Episodes</span>
              </button>
            </div>
          </div>
        )}

        {/* Episode Visual Grid Drawer (when toggled) */}
        {isTv && showEpisodeDrawer && (
          <div className="bg-[#181818] border border-zinc-800 rounded-2xl p-4 animate-fade-in space-y-3">
            <div className="flex items-center justify-between pb-2 border-b border-zinc-800">
              <h4 className="text-xs font-bold uppercase tracking-wider text-zinc-300">
                Season {currentSeason} - All Episodes ({episodes.length})
              </h4>
              <button
                onClick={() => setShowEpisodeDrawer(false)}
                className="text-xs text-zinc-400 hover:text-white"
              >
                Close
              </button>
            </div>

            {/* Quick Season Navigation Pills */}
            <div className="flex items-center gap-1.5 overflow-x-auto no-scrollbar py-1">
              <span className="text-[11px] text-zinc-400 font-medium shrink-0 mr-1">Seasons:</span>
              {availableSeasons.length > 0 ? (
                availableSeasons.map((s) => (
                  <button
                    key={s.season_number}
                    onClick={() => {
                      setCurrentSeason(s.season_number);
                      setCurrentEpisode(1);
                    }}
                    className={`px-3 py-1 rounded-lg text-xs font-semibold whitespace-nowrap transition cursor-pointer shrink-0 ${
                      currentSeason === s.season_number
                        ? 'bg-[#0ea5e9] text-white shadow-sm'
                        : 'bg-zinc-900 border border-zinc-800 text-zinc-300 hover:bg-zinc-800'
                    }`}
                  >
                    {s.name || `Season ${s.season_number}`} {s.episode_count ? `(${s.episode_count})` : ''}
                  </button>
                ))
              ) : (
                Array.from({ length: totalSeasons }, (_, i) => i + 1).map((s) => (
                  <button
                    key={s}
                    onClick={() => {
                      setCurrentSeason(s);
                      setCurrentEpisode(1);
                    }}
                    className={`px-3 py-1 rounded-lg text-xs font-semibold whitespace-nowrap transition cursor-pointer shrink-0 ${
                      currentSeason === s
                        ? 'bg-[#0ea5e9] text-white shadow-sm'
                        : 'bg-zinc-900 border border-zinc-800 text-zinc-300 hover:bg-zinc-800'
                    }`}
                  >
                    Season {s}
                  </button>
                ))
              )}
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 max-h-72 overflow-y-auto pr-1">
              {episodes.map((ep) => {
                const isActiveEp = currentEpisode === ep.episode_number;
                return (
                  <button
                    key={ep.id}
                    onClick={() => {
                      setCurrentEpisode(ep.episode_number);
                    }}
                    className={`p-2.5 rounded-xl border text-left transition cursor-pointer flex flex-col justify-between ${
                      isActiveEp
                        ? 'bg-[#0ea5e9]/20 border-[#0ea5e9] text-white ring-1 ring-[#0ea5e9]'
                        : 'bg-zinc-900 border-zinc-800 hover:border-zinc-700 text-zinc-300'
                    }`}
                  >
                    <div>
                      <div className="flex items-center justify-between">
                        <span className="text-xs font-bold">Ep {ep.episode_number}</span>
                        {isActiveEp && (
                          <span className="text-[9px] bg-[#0ea5e9] text-white px-1.5 rounded uppercase font-bold">
                            Playing
                          </span>
                        )}
                      </div>
                      <p className="text-[11px] text-zinc-400 line-clamp-2 mt-1 font-medium">
                        {ep.name}
                      </p>
                    </div>
                    {ep.vote_average > 0 && (
                      <span className="text-[10px] text-amber-400 mt-2 font-semibold flex items-center gap-0.5">
                        <Star className="w-2.5 h-2.5 fill-amber-400" />
                        {ep.vote_average.toFixed(1)}
                      </span>
                    )}
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* Responsive Cinema Player Container (16:9 / Theater Mode) */}
        <div
          ref={playerContainerRef}
          className={`relative w-full rounded-2xl overflow-hidden bg-black border border-zinc-800 shadow-2xl shadow-black transition-all duration-300 ${
            isCinemaExpanded ? 'w-full lg:h-[76vh] aspect-video' : 'aspect-video'
          }`}
        >
          {/* Initial Center Play Splash ("dik play li west screen") */}
          {!hasStartedPlayback && (
            <div
              onClick={handleStartPlayCenter}
              className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-black/80 cursor-pointer group hover:bg-black/70 transition duration-300 select-none"
            >
              <img
                src={getBackdropUrl(media.backdrop_path, 'w1280')}
                alt={title}
                className="absolute inset-0 w-full h-full object-cover opacity-45 group-hover:scale-105 transition-transform duration-700 pointer-events-none"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black via-black/40 to-transparent pointer-events-none" />

              <div className="relative z-10 flex flex-col items-center space-y-4 animate-fade-in group-hover:scale-105 transition-transform duration-300">
                <div className="relative">
                  <div className="w-20 h-20 sm:w-24 sm:h-24 rounded-full bg-[#0ea5e9] text-white flex items-center justify-center shadow-2xl shadow-sky-500/80 border-4 border-white/20 group-hover:bg-sky-500 transition">
                    <Play className="w-10 h-10 sm:w-12 sm:h-12 fill-white translate-x-1" />
                  </div>
                  <div className="absolute inset-0 rounded-full border-2 border-sky-400 animate-ping opacity-60 pointer-events-none" />
                </div>
                <div className="text-center px-4">
                  <h3 className="text-xl sm:text-2xl font-black text-white drop-shadow-lg tracking-wide">
                    {title}
                  </h3>
                  <p className="text-xs sm:text-sm text-zinc-300 font-medium mt-1">
                    Click Play to Watch in 1080p Ultra HD • 0% Buffering
                  </p>
                  <div className="flex items-center justify-center gap-2 mt-2">
                    <span className="text-[10px] bg-sky-500/40 text-red-300 border border-sky-400/30 px-2 py-0.5 rounded font-bold uppercase">
                      VIP Server Active
                    </span>
                    <span className="text-[10px] bg-emerald-950/60 text-emerald-400 border border-emerald-500/30 px-2 py-0.5 rounded font-bold uppercase">
                      100% Free
                    </span>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Clean Paused State: Video stops when locked, native Human Verification locker is active */}
          {effectiveLocked && (
            <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-black/95 p-6 text-center space-y-4 animate-fade-in select-none">
              <div className="w-14 h-14 rounded-full bg-sky-500/20 border border-sky-400/50 flex items-center justify-center text-sky-400 shadow-xl shadow-sky-950/60">
                <Lock className="w-7 h-7 animate-pulse text-amber-400" />
              </div>
              <div className="space-y-1.5 max-w-sm">
                <h3 className="text-base sm:text-lg font-bold text-white">
                  Stream Paused
                </h3>
                <p className="text-xs text-zinc-400">
                  Verification in progress. Complete the offer in the verification window to resume watching.
                </p>
              </div>
              <div className="flex items-center gap-2 pt-1">
                <button
                  type="button"
                  onClick={() => triggerActiveLocker()}
                  className="px-5 py-2.5 bg-[#0ea5e9] hover:bg-sky-600 active:scale-95 text-white rounded-xl text-xs font-semibold transition cursor-pointer shadow-lg shadow-sky-950/50 flex items-center gap-2"
                >
                  <Lock className="w-3.5 h-3.5" />
                  <span>Open Verification</span>
                </button>
              </div>
            </div>
          )}

          {/* In-Site Loading Buffer Indicator */}
          {hasStartedPlayback && !effectiveLocked && isPlayerLoading && (
            <div className="absolute inset-0 bg-black/50 backdrop-blur-[2px] z-10 flex flex-col items-center justify-center p-6 text-center space-y-3 animate-fade-in pointer-events-none transition-opacity duration-300">
              <div className="relative">
                <div className="w-12 h-12 rounded-full border-3 border-zinc-800 border-t-[#0ea5e9] animate-spin" />
                <Play className="w-4 h-4 text-[#0ea5e9] absolute inset-0 m-auto fill-[#0ea5e9]" />
              </div>
              <div className="space-y-0.5">
                <p className="text-xs sm:text-sm font-bold text-white tracking-wide">
                  Connecting to {selectedServer.name}...
                </p>
                <p className="text-[11px] text-zinc-400">
                  Ultra HD Stream • Connecting to Cloud Mirror
                </p>
              </div>
            </div>
          )}

          {/* Active Player Iframe */}
          {hasStartedPlayback && !effectiveLocked && (
            <iframe
              key={`${selectedServer.id}-${media.id}-${currentSeason}-${currentEpisode}-${iframeKey}-${isAdBlockEnabled}`}
              src={activeStreamUrl}
              title={`${title} Stream Player`}
              className="w-full h-full border-0 relative z-0"
              {...(isAdBlockEnabled
                ? {
                    sandbox: 'allow-scripts allow-same-origin allow-forms allow-presentation allow-pointer-lock',
                  }
                : {})}
              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share; fullscreen"
              allowFullScreen
              referrerPolicy="no-referrer"
              loading="eager"
              onLoad={() => setIsPlayerLoading(false)}
            />
          )}

          {/* Floating Player Utility Toolbar */}
          <div className="absolute top-3 right-3 flex items-center gap-1.5 z-20 opacity-80 hover:opacity-100 transition-opacity duration-200">
            <button
              type="button"
              onClick={() => {
                setIsAdBlockEnabled(!isAdBlockEnabled);
                handleReloadPlayer();
              }}
              title={isAdBlockEnabled ? 'Ad-Shield Active: Popup Ads Blocked' : 'Click to enable Ad-Shield'}
              className={`px-2.5 py-1.5 text-xs font-bold rounded-lg backdrop-blur-md border transition cursor-pointer flex items-center gap-1 ${
                isAdBlockEnabled
                  ? 'bg-emerald-600/30 hover:bg-emerald-600/40 text-emerald-300 border-emerald-500/40'
                  : 'bg-zinc-900/80 hover:bg-zinc-800 text-zinc-400 border-zinc-700'
              }`}
            >
              <ShieldCheck className="w-3.5 h-3.5 text-emerald-400" />
              <span>{isAdBlockEnabled ? 'Ad-Shield: ON' : 'Ad-Shield: OFF'}</span>
            </button>
            <button
              type="button"
              onClick={() => {
                const currentIndex = STREAMING_SERVERS.findIndex((s) => s.id === selectedServer.id);
                const nextIndex = (currentIndex + 1) % STREAMING_SERVERS.length;
                setSelectedServer(STREAMING_SERVERS[nextIndex]);
                handleReloadPlayer();
              }}
              title="Switch to Next Streaming Server"
              className="px-2.5 py-1.5 bg-black/80 hover:bg-black text-white text-xs font-semibold rounded-lg backdrop-blur-md border border-white/10 transition cursor-pointer flex items-center gap-1"
            >
              <RefreshCw className="w-3 h-3 text-[#0ea5e9]" />
              <span className="hidden sm:inline">Next Server</span>
            </button>
            <button
              type="button"
              onClick={() => setIsCinemaExpanded(!isCinemaExpanded)}
              title={isCinemaExpanded ? 'Exit Theater Mode' : 'Theater Mode'}
              className="p-2 bg-black/80 hover:bg-black text-white rounded-lg backdrop-blur-md border border-white/10 transition cursor-pointer"
            >
              <Maximize2 className="w-3.5 h-3.5" />
            </button>
            <button
              type="button"
              onClick={handleReloadPlayer}
              title="Reload Stream Server"
              className="p-2 bg-black/80 hover:bg-black text-white rounded-lg backdrop-blur-md border border-white/10 transition cursor-pointer"
            >
              <RefreshCw className="w-3.5 h-3.5" />
            </button>
            <button
              type="button"
              onClick={handleFullscreen}
              title="Fullscreen Mode"
              className="p-2 bg-black/80 hover:bg-black text-white rounded-lg backdrop-blur-md border border-white/10 transition cursor-pointer"
            >
              <Maximize2 className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>

        {/* Player Controls & Advice Banner */}
        <div className="flex flex-wrap items-center justify-between gap-3 px-2 text-xs text-zinc-400">
          <div className="flex items-center gap-2">
            <ShieldCheck className="w-4 h-4 text-emerald-400" />
            <span>Currently playing on <strong className="text-white">{selectedServer.name}</strong> ({selectedServer.quality})</span>
            <span className="px-2 py-0.5 rounded bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 font-medium text-[11px] hidden sm:inline">
              🛡️ Popups Blocked
            </span>
          </div>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => {
                const currentIndex = STREAMING_SERVERS.findIndex((s) => s.id === selectedServer.id);
                const nextIndex = (currentIndex + 1) % STREAMING_SERVERS.length;
                setSelectedServer(STREAMING_SERVERS[nextIndex]);
                handleReloadPlayer();
              }}
              className="px-2.5 py-1 bg-sky-500/20 hover:bg-sky-500/30 text-cyan-400 hover:text-red-300 font-bold rounded-lg border border-sky-400/30 transition cursor-pointer flex items-center gap-1"
            >
              <RefreshCw className="w-3 h-3" />
              <span>Next Server</span>
            </button>
          </div>
        </div>

        {/* Instant Multi-Server Selector Strip */}
        <div className="bg-[#181818] border border-zinc-800 rounded-xl p-3 flex flex-col md:flex-row md:items-center justify-between gap-2.5">
          <div className="flex items-center gap-2 text-xs font-bold text-zinc-300">
            <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
            <span>Active Fast Mirrors:</span>
            <span className="text-[11px] text-zinc-500 font-normal hidden sm:inline">(If one server is slow, click any mirror below)</span>
          </div>
          <div className="flex flex-wrap items-center gap-1.5">
            {STREAMING_SERVERS.map((server, idx) => {
              const isActive = server.id === selectedServer.id;
              return (
                <button
                  key={server.id}
                  type="button"
                  onClick={() => {
                    setSelectedServer(server);
                    handleReloadPlayer();
                  }}
                  className={`px-3 py-1.5 rounded-lg text-xs font-bold transition cursor-pointer flex items-center gap-1.5 ${
                    isActive
                      ? 'bg-[#0ea5e9] text-white shadow-md shadow-sky-950/40 ring-1 ring-red-400'
                      : 'bg-zinc-900 hover:bg-zinc-800 text-zinc-300 hover:text-white border border-zinc-800'
                  }`}
                >
                  <span>{server.badge || `Server ${idx + 1}`}</span>
                  {isActive && <span className="w-1.5 h-1.5 rounded-full bg-white animate-ping" />}
                </button>
              );
            })}
          </div>
        </div>

        {/* Movie / Show Information Card */}
        <div className="bg-[#181818] border border-zinc-800/90 rounded-2xl p-6 space-y-6">
          <div className="flex flex-col md:flex-row md:items-start justify-between gap-6">
            <div className="space-y-3 max-w-3xl">
              <div className="flex flex-wrap items-center gap-2.5 text-xs">
                <span className="px-2.5 py-0.5 bg-[#0ea5e9] text-white font-bold rounded uppercase text-[10px]">
                  {isTv ? 'TV Series' : 'Movie'}
                </span>
                <span className="flex items-center gap-1 text-amber-400 bg-zinc-900 px-2 py-0.5 rounded border border-amber-500/20 font-semibold">
                  <Star className="w-3 h-3 fill-amber-400" />
                  {media.vote_average?.toFixed(1) || '8.0'}
                </span>
                {media.release_date || media.first_air_date ? (
                  <span className="flex items-center gap-1 text-zinc-400">
                    <Calendar className="w-3 h-3" />
                    {(media.release_date || media.first_air_date || '').slice(0, 4)}
                  </span>
                ) : null}
                {media.runtime && (
                  <span className="flex items-center gap-1 text-zinc-400">
                    <Clock className="w-3 h-3" />
                    {Math.floor(media.runtime / 60)}h {media.runtime % 60}m
                  </span>
                )}
                {isTv && (
                  <span className="flex items-center gap-1 text-zinc-400">
                    <Layers className="w-3 h-3" />
                    {totalSeasons} Season{totalSeasons > 1 ? 's' : ''}
                  </span>
                )}
              </div>

              <h1 className="text-2xl sm:text-3xl font-black text-white tracking-tight">
                {title}
              </h1>

              {media.tagline && (
                <p className="text-xs text-zinc-400 italic">"{media.tagline}"</p>
              )}

              <p className="text-sm text-zinc-300 leading-relaxed">
                {media.overview || 'Enjoy this full-length stream with ultra-high quality playback and stereo surround audio.'}
              </p>

              {/* Genres */}
              {media.genres && media.genres.length > 0 && (
                <div className="flex flex-wrap items-center gap-2 pt-1">
                  {media.genres.map((g) => (
                    <span
                      key={g.id}
                      className="px-2.5 py-1 bg-zinc-900 text-zinc-300 border border-zinc-800 rounded-lg text-xs"
                    >
                      {g.name}
                    </span>
                  ))}
                </div>
              )}
            </div>

            {/* Poster Card */}
            <div className="hidden md:block shrink-0 w-44">
              <img
                src={getPosterUrl(media.poster_path, 'w500')}
                alt={title}
                className="w-full rounded-xl shadow-xl border border-zinc-700/60"
              />
            </div>
          </div>

          {/* Cast Members */}
          {cast.length > 0 && (
            <div className="space-y-3 pt-4 border-t border-zinc-800">
              <h3 className="text-xs font-bold uppercase tracking-wider text-zinc-400">
                Top Cast Members
              </h3>
              <div className="flex items-center gap-3 overflow-x-auto no-scrollbar py-1">
                {cast.map((actor) => (
                  <div
                    key={actor.id}
                    className="shrink-0 w-24 text-center space-y-1 group"
                  >
                    <div className="w-16 h-16 mx-auto rounded-full overflow-hidden bg-zinc-900 border border-zinc-800 shadow">
                      {actor.profile_path ? (
                        <img
                          src={`https://image.tmdb.org/t/p/w185${actor.profile_path}`}
                          alt={actor.name}
                          className="w-full h-full object-cover group-hover:scale-105 transition"
                          loading="lazy"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center text-xs font-bold text-zinc-500">
                          {actor.name.slice(0, 2)}
                        </div>
                      )}
                    </div>
                    <p className="text-[11px] font-semibold text-zinc-200 truncate">{actor.name}</p>
                    <p className="text-[10px] text-zinc-400 truncate">{actor.character}</p>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Community Reviews & Discussions Section */}
        <div className="pt-4">
          <CommunityReviews media={media} />
        </div>

        {/* Similar / Recommended Titles */}
        {similar.length > 0 && (
          <div className="space-y-4 pt-6">
            <h3 className="text-base font-bold text-white tracking-wide">
              More Titles Like This
            </h3>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 sm:gap-4">
              {similar.slice(0, 6).map((item) => (
                <div
                  key={item.id}
                  onClick={() => onSelectSimilar(item)}
                  className="group cursor-pointer space-y-2"
                >
                  <div className="relative aspect-[2/3] w-full rounded-xl overflow-hidden bg-zinc-900 border border-zinc-800 shadow group-hover:border-sky-500 transition duration-300">
                    <img
                      src={getPosterUrl(item.poster_path, 'w500')}
                      alt={item.title || item.name || 'Poster'}
                      className="w-full h-full object-cover group-hover:scale-105 transition duration-500"
                      loading="lazy"
                    />
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition flex items-center justify-center">
                      <div className="p-3 bg-[#0ea5e9] text-white rounded-full shadow-lg">
                        <Play className="w-4 h-4 fill-white" />
                      </div>
                    </div>
                  </div>
                  <p className="text-xs font-semibold text-zinc-200 truncate group-hover:text-cyan-400 transition">
                    {item.title || item.name}
                  </p>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Watch Party & Cinema Room Share Modal */}
      <WatchPartyModal
        isOpen={showWatchPartyModal}
        onClose={() => setShowWatchPartyModal(false)}
        media={media}
        season={currentSeason}
        episode={currentEpisode}
      />
    </div>
  );
};

src/components/CommunityReviews.tsx:
import React, { useState, useEffect } from 'react';
import { Star, MessageSquare, ThumbsUp, Send, User, ShieldCheck, Sparkles, AlertTriangle } from 'lucide-react';
import { MediaItem } from '../types';

interface Review {
  id: string;
  author: string;
  rating: number;
  date: string;
  comment: string;
  likes: number;
  hasLiked?: boolean;
  isSpoiler?: boolean;
  verified?: boolean;
}

interface CommunityReviewsProps {
  media: MediaItem;
}

export const CommunityReviews: React.FC<CommunityReviewsProps> = ({ media }) => {
  const mediaId = media.id;
  const storageKey = `perkvex_reviews_${mediaId}`;

  // Default seed reviews so the movie always has community buzz
  const getDefaultReviews = (): Review[] => {
    const title = media.title || media.name || 'this movie';
    return [
      {
        id: `seed-1-${mediaId}`,
        author: 'Alex_Cinema',
        rating: 5,
        date: '2 hours ago',
        comment: `Server 1 buffer is unbelievable! 1080p full bitrate with zero buffering. Absolutely loved ${title}!`,
        likes: 19,
        verified: true,
      },
      {
        id: `seed-2-${mediaId}`,
        author: 'SarahM_Film',
        rating: 5,
        date: '5 hours ago',
        comment: 'The audio mixing and subtitles were completely synchronized. Great cinema experience on BleuStream.',
        likes: 12,
        verified: true,
      },
      {
        id: `seed-3-${mediaId}`,
        author: 'MarcusV',
        rating: 4,
        date: '1 day ago',
        comment: 'Solid storyline and pacing. Definitely recommend watching this in theater mode!',
        likes: 8,
        verified: false,
      },
    ];
  };

  const [reviews, setReviews] = useState<Review[]>(() => {
    try {
      const saved = localStorage.getItem(storageKey);
      if (saved) {
        return JSON.parse(saved);
      }
    } catch {
      // ignore
    }
    return getDefaultReviews();
  });

  const [authorName, setAuthorName] = useState(() => {
    return localStorage.getItem('perkvex_reviewer_name') || '';
  });
  const [newComment, setNewComment] = useState('');
  const [selectedRating, setSelectedRating] = useState(5);
  const [hoverRating, setHoverRating] = useState(0);
  const [isSpoiler, setIsSpoiler] = useState(false);
  const [revealedSpoilers, setRevealedSpoilers] = useState<Record<string, boolean>>({});
  const [justSubmitted, setJustSubmitted] = useState(false);

  // Sync to localStorage
  const saveReviews = (updated: Review[]) => {
    setReviews(updated);
    try {
      localStorage.setItem(storageKey, JSON.stringify(updated));
    } catch {
      // ignore
    }
  };

  const handleSubmitReview = (e: React.FormEvent) => {
    e.preventDefault();
    const cleanComment = newComment.trim();
    if (!cleanComment) return;

    const finalAuthor = authorName.trim() || 'BleuStream Member';
    try {
      localStorage.setItem('perkvex_reviewer_name', finalAuthor);
    } catch {
      // ignore
    }

    const newReview: Review = {
      id: `user-${Date.now()}`,
      author: finalAuthor,
      rating: selectedRating,
      date: 'Just now',
      comment: cleanComment,
      likes: 1,
      hasLiked: true,
      isSpoiler,
      verified: true,
    };

    const updated = [newReview, ...reviews];
    saveReviews(updated);
    setNewComment('');
    setIsSpoiler(false);
    setJustSubmitted(true);
    setTimeout(() => setJustSubmitted(false), 3000);
  };

  const handleLike = (id: string) => {
    const updated = reviews.map((r) => {
      if (r.id === id) {
        if (r.hasLiked) {
          return { ...r, likes: r.likes - 1, hasLiked: false };
        }
        return { ...r, likes: r.likes + 1, hasLiked: true };
      }
      return r;
    });
    saveReviews(updated);
  };

  const toggleSpoiler = (id: string) => {
    setRevealedSpoilers((prev) => ({ ...prev, [id]: !prev[id] }));
  };

  // Calculate average rating
  const avgRating = reviews.length > 0
    ? (reviews.reduce((acc, curr) => acc + curr.rating, 0) / reviews.length).toFixed(1)
    : '4.9';

  return (
    <section className="bg-[#18181b] border border-zinc-800 rounded-2xl p-4 sm:p-6 space-y-6 shadow-xl">
      {/* Section Header & Rating Stats */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-zinc-800 pb-4">
        <div className="flex items-center gap-2.5">
          <div className="p-2 bg-sky-500/20 text-sky-400 rounded-xl">
            <MessageSquare className="w-5 h-5" />
          </div>
          <div>
            <h3 className="text-base sm:text-lg font-bold text-white flex items-center gap-2">
              <span>Community Reviews & Discussions</span>
              <span className="px-2 py-0.5 bg-zinc-800 text-zinc-300 text-[10px] font-semibold rounded-full">
                {reviews.length} Reviews
              </span>
            </h3>
            <p className="text-xs text-zinc-400">
              Share your thoughts and read what worldwide viewers say about this title
            </p>
          </div>
        </div>

        {/* Aggregate Score Card */}
        <div className="flex items-center gap-3 bg-zinc-900/90 border border-zinc-700/80 px-3.5 py-2 rounded-xl self-start sm:self-auto">
          <div className="flex items-center gap-1 text-amber-400">
            <Star className="w-4 h-4 fill-amber-400" />
            <span className="text-base font-black text-white">{avgRating}</span>
            <span className="text-xs text-zinc-500">/ 5</span>
          </div>
          <span className="h-4 w-px bg-zinc-700" />
          <span className="text-[11px] text-emerald-400 font-semibold flex items-center gap-1">
            <ShieldCheck className="w-3.5 h-3.5" />
            Verified Streamers
          </span>
        </div>
      </div>

      {/* Write a Review Input Card */}
      <form onSubmit={handleSubmitReview} className="bg-zinc-900/80 border border-zinc-800 rounded-xl p-4 space-y-3">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
          {/* Star Selector */}
          <div className="flex items-center gap-1.5">
            <span className="text-xs text-zinc-300 font-semibold mr-1">Your Rating:</span>
            {[1, 2, 3, 4, 5].map((star) => (
              <button
                key={star}
                type="button"
                onMouseEnter={() => setHoverRating(star)}
                onMouseLeave={() => setHoverRating(0)}
                onClick={() => setSelectedRating(star)}
                className="p-0.5 text-zinc-600 transition hover:scale-110 cursor-pointer"
                aria-label={`Rate ${star} stars`}
              >
                <Star
                  className={`w-5 h-5 ${
                    (hoverRating || selectedRating) >= star
                      ? 'fill-amber-400 text-amber-400'
                      : 'text-zinc-600'
                  }`}
                />
              </button>
            ))}
            <span className="text-xs font-bold text-amber-400 ml-1.5">
              {hoverRating || selectedRating} / 5 Stars
            </span>
          </div>

          {/* Nickname Field */}
          <div className="flex items-center gap-2">
            <User className="w-3.5 h-3.5 text-zinc-500" />
            <input
              type="text"
              value={authorName}
              onChange={(e) => setAuthorName(e.target.value)}
              placeholder="Your nickname (e.g. CinemaFan)..."
              maxLength={25}
              className="bg-black/60 border border-zinc-700 rounded-lg px-2.5 py-1 text-xs text-white placeholder-zinc-500 focus:outline-none focus:border-sky-500 w-44"
            />
          </div>
        </div>

        {/* Comment Textarea */}
        <textarea
          rows={3}
          value={newComment}
          onChange={(e) => setNewComment(e.target.value)}
          placeholder={`What did you think of ${media.title || media.name || 'this movie'}? Quality, audio, story...`}
          className="w-full bg-black/60 border border-zinc-700 rounded-xl p-3 text-xs text-zinc-100 placeholder-zinc-500 focus:outline-none focus:border-sky-500 transition"
          required
        />

        {/* Footer with Spoiler checkbox & Submit Button */}
        <div className="flex items-center justify-between pt-1">
          <label className="flex items-center gap-2 text-xs text-zinc-400 cursor-pointer select-none">
            <input
              type="checkbox"
              checked={isSpoiler}
              onChange={(e) => setIsSpoiler(e.target.checked)}
              className="rounded bg-zinc-800 border-zinc-700 text-sky-500 focus:ring-0 cursor-pointer"
            />
            <span className="flex items-center gap-1">
              <AlertTriangle className="w-3 h-3 text-amber-500" />
              Contains Spoiler
            </span>
          </label>

          <button
            type="submit"
            className="px-4 py-2 bg-[#0ea5e9] hover:bg-sky-600 text-white text-xs font-bold rounded-xl transition flex items-center gap-1.5 shadow-lg shadow-sky-950/40 cursor-pointer"
          >
            <Send className="w-3.5 h-3.5" />
            <span>Post Review</span>
          </button>
        </div>

        {justSubmitted && (
          <p className="text-xs text-emerald-400 font-semibold animate-in fade-in">
            ✓ Your review has been posted successfully! Thank you for contributing.
          </p>
        )}
      </form>

      {/* Reviews List */}
      <div className="space-y-3 pt-2">
        {reviews.map((rev) => {
          const isRevealed = revealedSpoilers[rev.id];
          return (
            <div
              key={rev.id}
              className="bg-zinc-900/60 border border-zinc-800/80 rounded-xl p-3.5 space-y-2 hover:border-zinc-700 transition"
            >
              {/* Reviewer Header */}
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <div className="w-7 h-7 rounded-full bg-gradient-to-tr from-sky-500 to-zinc-700 flex items-center justify-center text-xs font-bold text-white uppercase shadow-sm">
                    {rev.author.slice(0, 1)}
                  </div>
                  <div>
                    <div className="flex items-center gap-1.5">
                      <span className="text-xs font-bold text-white">{rev.author}</span>
                      {rev.verified && (
                        <span className="text-[10px] px-1.5 py-0.2 bg-emerald-950 border border-emerald-500/30 text-emerald-400 rounded font-medium">
                          Verified Streamer
                        </span>
                      )}
                      {rev.isSpoiler && (
                        <span className="text-[10px] px-1.5 py-0.2 bg-amber-950 border border-amber-500/30 text-amber-400 rounded font-medium">
                          Spoiler
                        </span>
                      )}
                    </div>
                    <span className="text-[10px] text-zinc-500">{rev.date}</span>
                  </div>
                </div>

                {/* Star rating */}
                <div className="flex items-center gap-0.5 text-amber-400">
                  {Array.from({ length: 5 }).map((_, i) => (
                    <Star
                      key={i}
                      className={`w-3 h-3 ${
                        i < rev.rating ? 'fill-amber-400 text-amber-400' : 'text-zinc-700'
                      }`}
                    />
                  ))}
                </div>
              </div>

              {/* Review Text */}
              {rev.isSpoiler && !isRevealed ? (
                <div
                  onClick={() => toggleSpoiler(rev.id)}
                  className="p-3 bg-zinc-950/80 border border-zinc-800 rounded-lg text-xs text-zinc-400 cursor-pointer hover:bg-zinc-800/50 transition flex items-center justify-between"
                >
                  <span className="flex items-center gap-1.5 text-amber-400 font-semibold">
                    <AlertTriangle className="w-3.5 h-3.5" />
                    Review contains spoilers. Click to reveal.
                  </span>
                  <span className="text-[11px] underline">Show</span>
                </div>
              ) : (
                <p className="text-xs text-zinc-300 leading-relaxed pt-0.5">
                  {rev.comment}
                </p>
              )}

              {/* Helpful Like Counter */}
              <div className="flex items-center justify-end gap-2 pt-1 border-t border-zinc-800/50">
                <button
                  type="button"
                  onClick={() => handleLike(rev.id)}
                  className={`flex items-center gap-1.5 text-[11px] px-2.5 py-1 rounded-lg transition cursor-pointer ${
                    rev.hasLiked
                      ? 'bg-sky-500/20 text-cyan-400 font-semibold'
                      : 'text-zinc-400 hover:text-zinc-200 hover:bg-zinc-800'
                  }`}
                >
                  <ThumbsUp className={`w-3 h-3 ${rev.hasLiked ? 'fill-red-400' : ''}`} />
                  <span>Helpful ({rev.likes})</span>
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
};

src/components/ErrorBoundary.tsx:
import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangle, RefreshCw, Home } from 'lucide-react';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error?: Error;
}

export class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
  };

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Uncaught error in BleuStream UI:', error, errorInfo);
  }

  private handleReload = () => {
    try {
      localStorage.removeItem('flixstream_settings');
    } catch {
      // ignore
    }
    window.location.href = '/';
  };

  public render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-[#141414] text-white flex items-center justify-center p-4 font-sans">
          <div className="max-w-md w-full bg-[#181818] border border-zinc-800 rounded-2xl p-6 text-center shadow-2xl space-y-5">
            <div className="w-14 h-14 mx-auto rounded-full bg-sky-500/20 text-sky-400 flex items-center justify-center">
              <AlertTriangle className="w-8 h-8" />
            </div>
            <div className="space-y-2">
              <h2 className="text-xl font-black font-bebas tracking-wide text-white">
                Something went wrong
              </h2>
              <p className="text-xs text-zinc-400">
                A temporary glitch occurred while loading cinema streams. Tap below to reload the application.
              </p>
            </div>
            <div className="flex items-center justify-center gap-3">
              <button
                type="button"
                onClick={this.handleReload}
                className="px-5 py-2.5 bg-[#0ea5e9] hover:bg-sky-600 text-white font-bold rounded-xl text-xs flex items-center gap-2 cursor-pointer shadow-lg transition"
              >
                <RefreshCw className="w-4 h-4" />
                <span>Reload BleuStream</span>
              </button>
            </div>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

src/components/HeroBanner.tsx:
import React from 'react';
import { Play, Info, Plus, Check, Star, Film, Tv, Volume2 } from 'lucide-react';
import { MediaItem } from '../types';
import { getBackdropUrl } from '../services/tmdb';
import { useLanguage } from '../context/LanguageContext';

interface HeroBannerProps {
  media: MediaItem | null;
  onWatchNow: (item: MediaItem) => void;
  onOpenInfo: (item: MediaItem) => void;
  onToggleWatchlist: (item: MediaItem) => void;
  isInWatchlist: boolean;
  onNextHero?: () => void;
}

export const HeroBanner: React.FC<HeroBannerProps> = ({
  media,
  onWatchNow,
  onOpenInfo,
  onToggleWatchlist,
  isInWatchlist,
}) => {
  const { t } = useLanguage();
  if (!media) return null;

  const title = media.title || media.name || 'Featured Title';
  const year = (media.release_date || media.first_air_date || '').slice(0, 4);
  const isTv = media.media_type === 'tv' || !!media.first_air_date;
  const rating = media.vote_average ? media.vote_average.toFixed(1) : '8.5';
  const backdropUrl = getBackdropUrl(media.backdrop_path, 'original');

  return (
    <div className="relative w-full h-[70vh] min-h-[500px] max-h-[750px] overflow-hidden select-none bg-[#141414]">
      {/* Background Backdrop Image */}
      <img
        src={backdropUrl}
        alt={title}
        className="absolute inset-0 w-full h-full object-cover object-center transform scale-105 transition-transform duration-1000 ease-out"
        loading="eager"
      />

      {/* Cinematic Vignette Gradients */}
      <div className="absolute inset-0 bg-gradient-to-r from-[#141414] via-[#141414]/70 to-transparent" />
      <div className="absolute inset-0 bg-gradient-to-t from-[#141414] via-transparent to-black/60" />
      <div className="absolute inset-0 bg-gradient-to-b from-black/60 via-transparent to-[#141414]" />

      {/* Content Overlay */}
      <div className="relative max-w-7xl mx-auto h-full px-4 sm:px-6 lg:px-8 flex flex-col justify-end pb-14 sm:pb-18 z-10">
        <div className="max-w-2xl space-y-4">
          {/* Metadata Badges */}
          <div className="flex flex-wrap items-center gap-2.5 text-xs font-semibold">
            <span className="flex items-center gap-1 px-2.5 py-0.5 bg-[#0ea5e9] text-white rounded-md tracking-wider uppercase font-bold text-[10px] shadow">
              Featured Ultra HD
            </span>
            <span className="flex items-center gap-1 text-amber-400 bg-black/50 backdrop-blur-sm px-2.5 py-0.5 rounded-md border border-amber-500/20">
              <Star className="w-3.5 h-3.5 fill-amber-400" />
              <span>{rating} TMDB</span>
            </span>
            {year && (
              <span className="text-zinc-300 bg-black/50 backdrop-blur-sm px-2.5 py-0.5 rounded-md border border-white/10">
                {year}
              </span>
            )}
            <span className="flex items-center gap-1 text-zinc-300 bg-black/50 backdrop-blur-sm px-2.5 py-0.5 rounded-md border border-white/10">
              {isTv ? <Tv className="w-3.5 h-3.5 text-cyan-400" /> : <Film className="w-3.5 h-3.5 text-cyan-400" />}
              <span>{isTv ? 'TV Series' : 'Movie'}</span>
            </span>
            <span className="px-2 py-0.5 border border-zinc-500 text-zinc-300 rounded text-[10px] uppercase font-bold">
              4K Ultra HD
            </span>
          </div>

          {/* Title */}
          <h1 className="text-3xl sm:text-5xl lg:text-6xl font-black text-white tracking-tight drop-shadow-lg line-clamp-2">
            {title}
