import React, { useEffect, useState } from 'react';
import { X, Play, Plus, Check, Star, Calendar, Clock, Film, Tv, Youtube, Layers } from 'lucide-react';
import { MediaItem } from '../types';
import { fetchDetails, getBackdropUrl, getPosterUrl } from '../services/tmdb';

interface MediaDetailModalProps {
  media: MediaItem;
  onClose: () => void;
  onPlay: (item: MediaItem) => void;
  onOpenTrailer: (item: MediaItem) => void;
  onToggleWatchlist: (item: MediaItem) => void;
  isInWatchlist: boolean;
}

export const MediaDetailModal: React.FC<MediaDetailModalProps> = ({
  media,
  onClose,
  onPlay,
  onOpenTrailer,
  onToggleWatchlist,
  isInWatchlist,
}) => {
  const [detailed, setDetailed] = useState<MediaItem>(media);
  const isTv = media.media_type === 'tv' || !!media.first_air_date;

  useEffect(() => {
    fetchDetails(isTv ? 'tv' : 'movie', media.id).then((res) => {
      if (res) setDetailed(res);
    });
  }, [media.id, isTv]);

  const title = detailed.title || detailed.name || 'Untitled';
  const year = (detailed.release_date || detailed.first_air_date || '').slice(0, 4);
  const rating = detailed.vote_average ? detailed.vote_average.toFixed(1) : '8.1';
  const backdropUrl = getBackdropUrl(detailed.backdrop_path, 'w1280');
  const posterUrl = getPosterUrl(detailed.poster_path, 'w500');

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-6 bg-black/85 backdrop-blur-md animate-fade-in overflow-y-auto">
      <div className="relative w-full max-w-3xl bg-[#181818] border border-zinc-700/80 rounded-2xl shadow-2xl overflow-hidden text-white my-auto">
        {/* Backdrop Banner Header */}
        <div className="relative h-64 sm:h-80 w-full overflow-hidden">
          <img
            src={backdropUrl}
            alt={title}
            className="w-full h-full object-cover"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-[#181818] via-[#181818]/60 to-black/40" />

          {/* Close Button */}
          <button
            type="button"
            onClick={onClose}
            className="absolute top-4 right-4 p-2 bg-black/70 hover:bg-black text-zinc-300 hover:text-white rounded-full backdrop-blur-md transition cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>

          {/* Title & Quick Actions over backdrop */}
          <div className="absolute inset-x-6 bottom-6 space-y-3">
            <div className="flex items-center gap-2 text-xs font-semibold">
              <span className="px-2 py-0.5 bg-[#0ea5e9] text-white rounded uppercase text-[10px] font-bold">
                {isTv ? 'TV Series' : 'Movie'}
              </span>
              <span className="flex items-center gap-1 text-amber-400 bg-black/70 px-2 py-0.5 rounded border border-amber-500/20">
                <Star className="w-3.5 h-3.5 fill-amber-400" />
                {rating}
              </span>
              {year && (
                <span className="text-zinc-300 bg-black/70 px-2 py-0.5 rounded">
                  {year}
                </span>
              )}
              <span className="text-[10px] px-2 py-0.5 border border-zinc-400/60 rounded uppercase font-bold text-zinc-300">
                Ultra HD
              </span>
            </div>

            <h2 className="text-2xl sm:text-4xl font-black text-white drop-shadow-md">
              {title}
            </h2>

            <div className="flex flex-wrap items-center gap-3 pt-1">
              <button
                type="button"
                onClick={() => onPlay(detailed)}
                className="px-6 py-2.5 bg-[#0ea5e9] hover:bg-sky-600 active:scale-95 text-white font-bold text-sm rounded-xl transition flex items-center gap-2 shadow-lg shadow-sky-950/50 cursor-pointer"
              >
                <Play className="w-4 h-4 fill-white" />
                <span>Stream Now</span>
              </button>

              <button
                type="button"
                onClick={() => onOpenTrailer(detailed)}
                className="px-4 py-2.5 bg-zinc-800/90 hover:bg-zinc-700 text-white text-sm font-medium rounded-xl border border-zinc-600/40 transition flex items-center gap-2 cursor-pointer"
              >
                <Youtube className="w-4 h-4 text-sky-400" />
                <span>Trailer</span>
              </button>

              <button
                type="button"
                onClick={() => onToggleWatchlist(detailed)}
                className="p-2.5 bg-zinc-800/90 hover:bg-zinc-700 text-white rounded-xl border border-zinc-600/40 transition cursor-pointer"
                title={isInWatchlist ? 'Remove from My List' : 'Add to My List'}
              >
                {isInWatchlist ? (
                  <Check className="w-5 h-5 text-emerald-400" />
                ) : (
                  <Plus className="w-5 h-5" />
                )}
              </button>
            </div>
          </div>
        </div>

        {/* Content Body */}
        <div className="p-6 space-y-5">
          {detailed.tagline && (
            <p className="text-xs text-cyan-400 font-medium italic">
              "{detailed.tagline}"
            </p>
          )}

          <div className="flex flex-col sm:flex-row gap-6">
            <div className="space-y-4 flex-1">
              <p className="text-sm text-zinc-300 leading-relaxed">
                {detailed.overview || 'No synopsis provided for this title.'}
              </p>

              {/* Genre Pills */}
              {detailed.genres && detailed.genres.length > 0 && (
                <div className="flex flex-wrap gap-2 pt-2">
                  {detailed.genres.map((g) => (
                    <span
                      key={g.id}
                      className="px-2.5 py-1 bg-zinc-800/80 border border-zinc-700/60 rounded-lg text-xs text-zinc-300 font-medium"
                    >
                      {g.name}
                    </span>
                  ))}
                </div>
              )}
            </div>

            {/* Meta Info Side Column */}
            <div className="w-full sm:w-56 shrink-0 bg-zinc-900/80 border border-zinc-800/80 rounded-xl p-4 space-y-3 text-xs">
              <div>
                <span className="text-zinc-400 block text-[11px]">Audio & Quality:</span>
                <span className="text-white font-medium">Dolby Atmos / 4K Ultra HD</span>
              </div>
              {detailed.runtime ? (
                <div>
                  <span className="text-zinc-400 block text-[11px]">Runtime:</span>
                  <span className="text-white font-medium">
                    {Math.floor(detailed.runtime / 60)}h {detailed.runtime % 60}m
                  </span>
                </div>
              ) : null}
              {detailed.number_of_seasons ? (
                <div>
                  <span className="text-zinc-400 block text-[11px]">Seasons:</span>
                  <span className="text-white font-medium">
                    {detailed.number_of_seasons} Seasons ({detailed.number_of_episodes || 0} Episodes)
                  </span>
                </div>
              ) : null}
              <div>
                <span className="text-zinc-400 block text-[11px]">Mirrors:</span>
                <span className="text-emerald-400 font-semibold">6 Live Servers Online</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

src/components/Navbar.tsx:
import React, { useState, useEffect, useRef } from 'react';
import { Search, Film, Tv, Flame, Bookmark, History, X, Star, Menu, Play, Home, Sparkles, Loader2, ArrowRight, BookOpen } from 'lucide-react';
import { MediaItem } from '../types';
import { searchCatalog, getPosterUrl } from '../services/tmdb';
import { LanguageSelector } from './LanguageSelector';
import { useLanguage } from '../context/LanguageContext';

interface NavbarProps {
  currentTab: 'home' | 'movies' | 'tv' | 'anime' | 'trending' | 'watchlist' | 'history' | 'search' | 'articles';
  onSelectTab: (tab: 'home' | 'movies' | 'tv' | 'anime' | 'trending' | 'watchlist' | 'history' | 'search' | 'articles') => void;
  onOpenMedia: (item: MediaItem) => void;
  onSearchSubmit?: (query: string) => void;
  onOpenSettings?: () => void;
  watchlistCount: number;
}

export const Navbar: React.FC<NavbarProps> = ({
  currentTab,
  onSelectTab,
  onOpenMedia,
  onSearchSubmit,
  watchlistCount,
}) => {
  const { t } = useLanguage();
  const [isScrolled, setIsScrolled] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<MediaItem[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [showSearchDropdown, setShowSearchDropdown] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [mobileSearchOpen, setMobileSearchOpen] = useState(false);

  const searchRef = useRef<HTMLDivElement>(null);
  const desktopInputRef = useRef<HTMLInputElement>(null);
  const mobileInputRef = useRef<HTMLInputElement>(null);

  const handleLogoClick = () => {
    onSelectTab('home');
    setMobileMenuOpen(false);
    setMobileSearchOpen(false);
  };

  // Scroll listener for translucent Netflix-style blur navbar
  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 20) {
        setIsScrolled(true);
      } else {
        setIsScrolled(false);
      }
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Auto-focus mobile input when mobile search is opened
  useEffect(() => {
    if (mobileSearchOpen && mobileInputRef.current) {
      mobileInputRef.current.focus();
    }
  }, [mobileSearchOpen]);

  // Search debounce for quick live hints
  useEffect(() => {
    if (!searchQuery.trim()) {
      setSearchResults([]);
      setIsSearching(false);
      setShowSearchDropdown(false);
      return;
    }

    setIsSearching(true);
    const timer = setTimeout(async () => {
      try {
        const results = await searchCatalog(searchQuery);
        setSearchResults(results.slice(0, 8));
        setShowSearchDropdown(true);
      } catch (err) {
        console.error('Search error', err);
      } finally {
        setIsSearching(false);
      }
    }, 250);

    return () => clearTimeout(timer);
  }, [searchQuery]);

  // Click outside to close search dropdown
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(e.target as Node)) {
        setShowSearchDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Submit search on Enter key or Search button click
  const handleSearchSubmit = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    const query = searchQuery.trim();
    if (!query) return;

    setShowSearchDropdown(false);
    setMobileSearchOpen(false);

    if (onSearchSubmit) {
      onSearchSubmit(query);
    } else {
      onSelectTab('search');
    }
  };

  interface NavLinkItem {
    id: 'home' | 'movies' | 'tv' | 'anime' | 'trending' | 'watchlist' | 'history' | 'articles';
    label: string;
    icon?: React.ComponentType<{ className?: string }>;
    count?: number;
    badge?: string;
  }

  const navLinks: NavLinkItem[] = [
    { id: 'home', label: t('home'), icon: Home },
    { id: 'movies', label: t('movies'), icon: Film },
    { id: 'tv', label: t('tv'), icon: Tv },
    { id: 'anime', label: t('anime'), icon: Sparkles, badge: 'HOT' },
    { id: 'trending', label: t('trending'), icon: Flame },
    { id: 'watchlist', label: t('watchlist'), count: watchlistCount, icon: Bookmark },
    { id: 'history', label: t('history'), icon: History },
  ];

  return (
    <header
      className={`fixed top-0 inset-x-0 z-40 transition-all duration-300 ${
        isScrolled
          ? 'bg-[#141414]/95 backdrop-blur-md shadow-lg border-b border-white/5 py-2.5'
          : 'bg-gradient-to-b from-black/90 via-black/50 to-transparent py-4'
      }`}
    >
      <div className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8 flex items-center justify-between gap-3">
        {/* Left: Brand Logo & Main Nav */}
        <div className="flex items-center gap-4 lg:gap-8">
          <button
            type="button"
            onClick={handleLogoClick}
            className="flex items-center gap-1.5 focus:outline-none cursor-pointer group shrink-0"
          >
            <span className="text-2xl sm:text-3xl font-black font-bebas tracking-wider text-sky-400 group-hover:scale-105 transition">
              BLEU<span className="text-cyan-300">STREAM</span>
            </span>
            <span className="px-1.5 py-0.5 text-[10px] font-black uppercase bg-gradient-to-r from-sky-500 to-cyan-400 text-slate-950 font-bold rounded font-sans tracking-widest shadow-md shadow-sky-500/20">
              UHD
            </span>
          </button>

          {/* Desktop Navigation */}
          <nav className="hidden md:flex items-center gap-1 lg:gap-2">
            {navLinks.map((link) => {
              const active = currentTab === link.id;
              return (
                <button
                  key={link.id}
                  onClick={() => onSelectTab(link.id)}
                  className={`px-3 py-1.5 text-xs lg:text-sm font-medium rounded-full transition relative flex items-center gap-1.5 cursor-pointer ${
                    active
                      ? 'text-white bg-white/10 shadow-sm'
                      : 'text-zinc-400 hover:text-zinc-100 hover:bg-white/5'
                  }`}
                >
                  <span>{link.label}</span>
                  {link.badge && (
                    <span className="px-1.5 py-0.2 bg-gradient-to-r from-sky-500 to-pink-600 text-[8px] text-white rounded-full font-black uppercase tracking-wider">
                      {link.badge}
                    </span>
                  )}
                  {link.count !== undefined && link.count > 0 && (
                    <span className="px-1.5 py-0.2 bg-[#0ea5e9] text-[10px] text-white rounded-full font-bold">
                      {link.count}
                    </span>
                  )}
                </button>
              );
            })}
          </nav>
        </div>

        {/* Right: Search Box (Desktop) + Language Selector + Mobile Action Icons */}
        <div className="flex items-center gap-2 sm:gap-3">
          {/* Language Selector (Pill Dropdown next to Search) */}
          <LanguageSelector className="shrink-0" />

          {/* Desktop Search Box with Live Dropdown */}
          <div ref={searchRef} className="relative hidden md:block w-52 lg:w-68">
            <form onSubmit={handleSearchSubmit} className="relative flex items-center">
              <button
                type="submit"
                aria-label="Submit search"
                className="absolute left-2.5 text-zinc-400 hover:text-white transition p-0.5 cursor-pointer"
              >
                {isSearching ? (
                  <Loader2 className="w-4 h-4 text-sky-400 animate-spin" />
                ) : (
                  <Search className="w-4 h-4" />
                )}
              </button>
              <input
                ref={desktopInputRef}
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    handleSearchSubmit(e);
                  }
                }}
                onFocus={() => {
                  if (searchResults.length > 0 || searchQuery.trim()) setShowSearchDropdown(true);
                }}
                placeholder={t('search_placeholder')}
                className="w-full pl-9 pr-8 py-1.5 bg-black/70 border border-zinc-700/80 focus:border-[#0ea5e9] focus:bg-black rounded-full text-xs text-zinc-100 placeholder-zinc-500 outline-none transition duration-200"
              />
              {searchQuery && (
                <button
                  type="button"
                  onClick={() => {
                    setSearchQuery('');
                    setSearchResults([]);
                    setShowSearchDropdown(false);
                  }}
                  className="absolute right-2.5 text-zinc-400 hover:text-white transition cursor-pointer"
                >
                  <X className="w-3.5 h-3.5" />
                </button>
              )}
            </form>

            {/* Dropdown Results (Desktop) */}
            {showSearchDropdown && searchQuery.trim() && (
              <div className="absolute top-full mt-2 right-0 w-80 sm:w-96 max-h-[480px] overflow-y-auto bg-[#181818] border border-zinc-700/80 rounded-2xl shadow-2xl p-2 z-50 animate-fade-in divide-y divide-zinc-800">
                <div className="px-3 py-1.5 text-[11px] font-semibold text-zinc-400 uppercase tracking-wider flex items-center justify-between">
                  <span>Search for "{searchQuery}"</span>
                  <span className="text-zinc-400">
                    {isSearching ? 'Searching...' : `${searchResults.length} found`}
                  </span>
                </div>
                <div className="pt-1">
                  {searchResults.length === 0 && !isSearching ? (
                    <div className="p-4 text-center text-xs text-zinc-400">
                      Press <kbd className="px-1.5 py-0.5 bg-zinc-800 rounded font-mono">Enter</kbd> to search the entire global catalog.
                    </div>
                  ) : (
                    searchResults.map((item) => {
                      const title = item.title || item.name || 'Untitled';
                      const year = (item.release_date || item.first_air_date || '').slice(0, 4);
                      const isTv = item.media_type === 'tv' || !!item.first_air_date;

                      return (
                        <button
                          key={item.id}
                          type="button"
                          onClick={() => {
                            setShowSearchDropdown(false);
                            onOpenMedia(item);
                          }}
                          className="w-full flex items-center gap-3 p-2 rounded-xl hover:bg-zinc-800/80 transition text-left cursor-pointer group"
                        >
                          <img
                            src={getPosterUrl(item.poster_path, 'w342')}
                            alt={title}
                            className="w-10 h-14 object-cover rounded-md shrink-0 bg-zinc-900 border border-zinc-800 shadow group-hover:scale-105 transition"
                            loading="lazy"
                          />
                          <div className="flex-1 min-w-0">
                            <p className="text-xs font-semibold text-white truncate group-hover:text-cyan-400 transition">
                              {title}
                            </p>
                            <div className="flex items-center gap-2 text-[11px] text-zinc-400 mt-0.5">
                              {year && <span>{year}</span>}
                              <span className="px-1.5 py-0.2 bg-zinc-800 text-[10px] text-zinc-300 rounded uppercase font-medium">
                                {isTv ? 'TV Show' : 'Movie'}
                              </span>
                              <span className="flex items-center gap-0.5 text-amber-400 font-semibold">
                                <Star className="w-3 h-3 fill-amber-400" />
                                {item.vote_average?.toFixed(1) || '7.5'}
                              </span>
                            </div>
                          </div>
                          <div className="p-1.5 bg-[#0ea5e9]/20 group-hover:bg-[#0ea5e9] text-cyan-400 group-hover:text-white rounded-lg transition shrink-0">
                            <Play className="w-3.5 h-3.5 fill-current" />
                          </div>
                        </button>
                      );
                    })
                  )}
                </div>

                {/* View All Search Results button */}
                <div className="pt-2 pb-1 px-1">
                  <button
                    type="button"
                    onClick={() => handleSearchSubmit()}
                    className="w-full py-2 px-3 bg-[#0ea5e9] hover:bg-sky-600 text-white text-xs font-bold rounded-xl transition flex items-center justify-center gap-2 shadow cursor-pointer"
                  >
                    <span>View all results for "{searchQuery}"</span>
                    <ArrowRight className="w-3.5 h-3.5" />
                  </button>
                </div>
              </div>
            )}
          </div>

          {/* Mobile Dedicated Search Icon Button */}
          <button
            type="button"
            onClick={() => {
              setMobileSearchOpen(!mobileSearchOpen);
              setMobileMenuOpen(false);
            }}
            aria-label="Toggle mobile search"
            className={`md:hidden p-2 rounded-lg transition cursor-pointer ${
              mobileSearchOpen || currentTab === 'search' ? 'bg-[#0ea5e9] text-white' : 'text-zinc-300 hover:text-white bg-zinc-900/80 border border-zinc-800'
            }`}
          >
            <Search className="w-4 h-4" />
          </button>

          {/* Mobile Menu Hamburger Button */}
          <button
            type="button"
            onClick={() => {
              setMobileMenuOpen(!mobileMenuOpen);
              setMobileSearchOpen(false);
            }}
            aria-label="Toggle navigation menu"
            className="md:hidden p-2 text-zinc-300 hover:text-white bg-zinc-900/80 border border-zinc-800 rounded-lg cursor-pointer"
          >
            {mobileMenuOpen ? <X className="w-4 h-4" /> : <Menu className="w-4 h-4" />}
          </button>
        </div>
      </div>

      {/* Full-Width Mobile Search Bar & Live Dropdown Overlay */}
      {mobileSearchOpen && (
        <div className="md:hidden bg-[#181818] border-b border-zinc-800 px-3 py-3 space-y-3 animate-fade-in shadow-2xl">
          <form onSubmit={handleSearchSubmit} className="relative flex items-center gap-2">
            <div className="relative flex-1 flex items-center">
              <Search className="w-4 h-4 text-zinc-400 absolute left-3 pointer-events-none" />
              <input
                ref={mobileInputRef}
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    handleSearchSubmit(e);
                  }
                }}
                placeholder="Search all movies, series, anime (Enter)..."
                className="w-full pl-9 pr-9 py-2 bg-black/90 border border-zinc-700 focus:border-[#0ea5e9] rounded-xl text-xs text-white placeholder-zinc-500 outline-none"
              />
              {searchQuery && (
                <button
                  type="button"
                  onClick={() => setSearchQuery('')}
                  className="absolute right-3 text-zinc-400 hover:text-white p-1"
                >
                  <X className="w-3.5 h-3.5" />
                </button>
              )}
            </div>
            <button
              type="submit"
              className="px-3.5 py-2 bg-[#0ea5e9] text-white text-xs font-bold rounded-xl active:scale-95 transition cursor-pointer"
            >
              {isSearching ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Search'}
            </button>
          </form>

          {/* Mobile Search Results */}
          {searchQuery.trim() && (
            <div className="max-h-[65vh] overflow-y-auto divide-y divide-zinc-850 pt-1 space-y-1">
              <div className="pb-1.5 text-[11px] font-semibold text-zinc-400 flex items-center justify-between">
                <span>Quick Results for "{searchQuery}"</span>
                <span>{isSearching ? 'Searching...' : `${searchResults.length} found`}</span>
              </div>
              
              {searchResults.map((item) => {
                const title = item.title || item.name || 'Untitled';
                const year = (item.release_date || item.first_air_date || '').slice(0, 4);
                const isTv = item.media_type === 'tv' || !!item.first_air_date;

                return (
                  <button
                    key={item.id}
                    type="button"
                    onClick={() => {
                      setMobileSearchOpen(false);
                      onOpenMedia(item);
                    }}
                    className="w-full flex items-center gap-3 py-2 px-2 hover:bg-zinc-800/80 rounded-xl transition text-left cursor-pointer"
                  >
                    <img
                      src={getPosterUrl(item.poster_path, 'w342')}
                      alt={title}
                      className="w-10 h-14 object-cover rounded-md shrink-0 bg-zinc-900 border border-zinc-800"
                      loading="lazy"
                    />
                    <div className="flex-1 min-w-0">
                      <p className="text-xs font-semibold text-white truncate">
                        {title}
                      </p>
                      <div className="flex items-center gap-2 text-[11px] text-zinc-400 mt-0.5">
                        {year && <span>{year}</span>}
                        <span className="px-1.5 py-0.2 bg-zinc-800 text-[10px] text-zinc-300 rounded uppercase font-medium">
                          {isTv ? 'TV' : 'Movie'}
                        </span>
                        <span className="flex items-center gap-0.5 text-amber-400 font-semibold">
                          <Star className="w-3 h-3 fill-amber-400" />
                          {item.vote_average?.toFixed(1) || '7.5'}
                        </span>
                      </div>
                    </div>
                    <div className="p-1.5 bg-[#0ea5e9] text-white rounded-lg shrink-0">
                      <Play className="w-3.5 h-3.5 fill-current" />
                    </div>
                  </button>
                );
              })}

              <div className="pt-2">
                <button
                  type="button"
                  onClick={() => handleSearchSubmit()}
                  className="w-full py-2.5 bg-[#0ea5e9] text-white text-xs font-bold rounded-xl flex items-center justify-center gap-2 shadow cursor-pointer"
                >
                  <span>See all full search results for "{searchQuery}"</span>
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Mobile Drawer Menu */}
      {mobileMenuOpen && (
        <div className="md:hidden bg-[#181818] border-b border-zinc-800 px-4 py-3 space-y-2 animate-fade-in shadow-2xl">
          {navLinks.map((link) => {
            const active = currentTab === link.id;
            const Icon = link.icon;
            return (
              <button
                key={link.id}
                onClick={() => {
                  onSelectTab(link.id);
                  setMobileMenuOpen(false);
                }}
                className={`w-full flex items-center justify-between px-3 py-2 text-xs font-medium rounded-lg transition ${
                  active ? 'bg-[#0ea5e9] text-white' : 'text-zinc-300 hover:bg-zinc-800'
                }`}
              >
                <div className="flex items-center gap-2">
                  {Icon && <Icon className="w-4 h-4" />}
                  <span>{link.label}</span>
                </div>
                {link.count !== undefined && link.count > 0 && (
                  <span className="px-2 py-0.5 bg-white text-[#0ea5e9] text-[10px] font-bold rounded-full">
                    {link.count}
                  </span>
                )}
              </button>
            );
          })}
        </div>
      )}
    </header>
  );
};

src/components/SettingsModal.tsx:
import React, { useState } from 'react';
import { X, Key, Shield, Clock, Download, Check, RefreshCw, Sparkles, Database, Cloud, Layers, Zap } from 'lucide-react';
import { AppSettings } from '../types';
import { DEFAULT_TMDB_API_KEY } from '../services/tmdb';
import { generateAndDownloadZip } from '../utils/exportZip';
import { lockerConfig, LockerProvider } from '../services/lockerConfig';
import { triggerActiveLocker } from '../utils/locker';

interface SettingsModalProps {
  settings: AppSettings;
  onSave: (newSettings: AppSettings) => void;
  onClose: () => void;
  onTriggerTestLocker: () => void;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({
  settings,
  onSave,
  onClose,
  onTriggerTestLocker,
}) => {
  const [apiKey, setApiKey] = useState(settings.tmdbApiKey);
  const [lockerEnabled, setLockerEnabled] = useState(settings.lockerEnabled);
  const [provider, setProvider] = useState<LockerProvider>(() => lockerConfig.get().provider || 'ogads');
  const [lockerId, setLockerId] = useState(() => {
    const id = lockerConfig.get().lockerId || settings.lockerId;
    return (id && id !== 'o4e5p2') ? id : '4o7vvr';
  });
  const [adBlueIt, setAdBlueIt] = useState<string | number>(() => lockerConfig.get().adBlueMedia?.it ?? 4192251);
  const [adBlueKey, setAdBlueKey] = useState<string>(() => lockerConfig.get().adBlueMedia?.key || 'db00c');
  const [triggerOnPlay, setTriggerOnPlay] = useState<boolean>(() => lockerConfig.get().triggerOnPlay ?? true);
  const [delaySeconds, setDelaySeconds] = useState(settings.lockerDelaySeconds);
  const [savedSuccess, setSavedSuccess] = useState(false);
  const [downloadingZip, setDownloadingZip] = useState(false);
  const [relockedSuccess, setRelockedSuccess] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const cleanId = (lockerId.trim() && lockerId.trim() !== 'o4e5p2') ? lockerId.trim() : '4o7vvr';
    lockerConfig.updateConfig({
      provider,
      enabled: lockerEnabled,
      lockerId: cleanId,
      triggerOnPlay,
      delaySeconds: Math.max(0, Number(delaySeconds) || 0),
      adBlueMedia: {
        ...lockerConfig.get().adBlueMedia,
        it: adBlueIt ? (Number(adBlueIt) || adBlueIt) : 4192251,
        key: adBlueKey.trim() || 'db00c',
      },
    });
    onSave({
      tmdbApiKey: apiKey.trim() || DEFAULT_TMDB_API_KEY,
      lockerEnabled,
      lockerId: cleanId,
      lockerDelaySeconds: Math.max(0, Number(delaySeconds) || 0),
    });
    setSavedSuccess(true);
    setTimeout(() => {
      setSavedSuccess(false);
      onClose();
    }, 800);
  };

  const handleDownload = async () => {
    setDownloadingZip(true);
    try {
      await generateAndDownloadZip();
    } catch (err) {
      console.error('Download error:', err);
    } finally {
      setDownloadingZip(false);
    }
  };

  const handleResetDefault = () => {
    setApiKey(DEFAULT_TMDB_API_KEY);
    setLockerEnabled(true);
    setLockerId('4o7vvr');
    setDelaySeconds(20);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/85 backdrop-blur-md animate-fade-in">
      <div className="relative w-full max-w-xl bg-[#181818] border border-zinc-700/70 rounded-2xl shadow-2xl overflow-hidden text-white">
        {/* Header */}
        <div className="px-6 py-4 bg-[#202020] border-b border-zinc-800 flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <div className="p-2 bg-sky-500/20 text-sky-400 rounded-lg">
              <Shield className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-base font-bold tracking-wide">BleuStream Settings</h2>
              <p className="text-xs text-zinc-400">Configure TMDB API and CPA Locker Settings</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 text-zinc-400 hover:text-white rounded-lg hover:bg-zinc-800 transition cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="p-6 space-y-6">
          {/* TMDB API Key */}
          <div className="space-y-2">
            <label className="flex items-center justify-between text-xs font-semibold text-zinc-200">
              <span className="flex items-center gap-1.5">
                <Key className="w-3.5 h-3.5 text-amber-400" /> TMDB v3 API Key
              </span>
              <button
                type="button"
                onClick={() => setApiKey(DEFAULT_TMDB_API_KEY)}
                className="text-[11px] text-cyan-400 hover:text-red-300 transition"
              >
                Use Default Working Key
              </button>
            </label>
            <input
              type="text"
              value={apiKey}
              onChange={(e) => setApiKey(e.target.value)}
              placeholder="e.g. abdde991ce2a56652d4c0ca156db7836"
              className="w-full px-3.5 py-2.5 bg-black/60 border border-zinc-700 focus:border-sky-400 rounded-xl text-sm font-mono text-zinc-100 placeholder-zinc-500 outline-none transition"
            />
            <p className="text-[11px] text-zinc-400 flex items-center gap-1">
              <Database className="w-3 h-3 text-emerald-400" />
              Connected to The Movie Database catalog for high-resolution posters and live metadata.
            </p>
          </div>

          {/* CPA Locker Configuration */}
          <div className="p-4 bg-zinc-900/80 border border-zinc-800 rounded-xl space-y-4">
            <div className="flex items-center justify-between">
              <div>
                <span className="text-sm font-semibold text-zinc-100 flex items-center gap-1.5">
                  <Shield className="w-4 h-4 text-sky-400" /> OGAds CPA Locker
                </span>
                <p className="text-xs text-zinc-400">
                  Activates Human Verification locker (LAST())
                </p>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input
                  type="checkbox"
                  checked={lockerEnabled}
                  onChange={(e) => setLockerEnabled(e.target.checked)}
                  className="sr-only peer"
                />
                <div className="w-11 h-6 bg-zinc-700 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-zinc-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-[#0ea5e9]"></div>
              </label>
            </div>

            {lockerEnabled && (
              <div className="space-y-4 pt-3 border-t border-zinc-800">
                {/* Platform Selector */}
                <div className="space-y-1.5">
                  <label className="text-xs font-semibold text-zinc-300 flex items-center gap-1.5">
                    <Layers className="w-3.5 h-3.5 text-amber-400" />
                    <span>CPA Network Provider</span>
                  </label>
                  <div className="grid grid-cols-2 gap-2">
                    <button
                      type="button"
                      onClick={() => setProvider('adbluemedia')}
                      className={`p-2.5 rounded-lg border text-left cursor-pointer transition ${
                        provider === 'adbluemedia'
                          ? 'bg-blue-600/20 border-cyan-500 text-cyan-300 font-bold'
                          : 'bg-zinc-900 border-zinc-700 text-zinc-400'
                      }`}
                    >
                      <div className="text-xs">AdBlueMedia</div>
                      <div className="text-[10px] text-zinc-400">CloudFront + _Ri()</div>
                    </button>
                    <button
                      type="button"
                      onClick={() => setProvider('ogads')}
                      className={`p-2.5 rounded-lg border text-left cursor-pointer transition ${
                        provider === 'ogads'
                          ? 'bg-sky-500/20 border-sky-400 text-red-300 font-bold'
                          : 'bg-zinc-900 border-zinc-700 text-zinc-400'
                      }`}
                    >
                      <div className="text-xs">OGAds Native</div>
                      <div className="text-[10px] text-zinc-400">AppSave Locker ID</div>
                    </button>
                  </div>
                </div>

                {/* AdBlueMedia inputs */}
                {provider === 'adbluemedia' ? (
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 p-3 bg-blue-950/30 border border-blue-500/30 rounded-lg">
                    <div className="space-y-1">
                      <label className="text-xs font-medium text-cyan-300">Campaign `it` ID</label>
                      <input
                        type="text"
                        value={adBlueIt}
                        onChange={(e) => setAdBlueIt(e.target.value)}
                        placeholder="e.g. 4192251"
                        className="w-full px-3 py-1.5 bg-black/70 border border-zinc-700 focus:border-cyan-500 rounded-lg text-xs font-mono text-cyan-400 outline-none"
                      />
                    </div>
                    <div className="space-y-1">
                      <label className="text-xs font-medium text-cyan-300">Security `key`</label>
                      <input
                        type="text"
                        value={adBlueKey}
                        onChange={(e) => setAdBlueKey(e.target.value)}
                        placeholder="e.g. db00c"
                        className="w-full px-3 py-1.5 bg-black/70 border border-zinc-700 focus:border-cyan-500 rounded-lg text-xs font-mono text-cyan-400 outline-none"
                      />
                    </div>
                    <div className="col-span-full text-[10px] font-mono text-cyan-400/80">
                      Recall: <code className="bg-black/60 px-1 py-0.5 rounded">&lt;script&gt;_Ri();&lt;/script&gt;</code>
                    </div>
                  </div>
                ) : (
                  <div className="space-y-1.5 p-3 bg-zinc-900 border border-zinc-800 rounded-lg">
                    <label className="text-xs font-medium text-zinc-300">OGAds Locker ID</label>
                    <input
                      type="text"
                      value={lockerId}
                      onChange={(e) => setLockerId(e.target.value)}
                      placeholder="e.g. o4e5p2"
                      className="w-full px-3 py-2 bg-black/70 border border-zinc-700 focus:border-sky-400 rounded-lg text-xs font-mono text-zinc-100 outline-none"
                    />
                    <span className="text-[10px] text-zinc-400 font-mono">Active ID: {lockerId}</span>
                  </div>
                )}

                {/* Trigger Timing */}
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-1">
                  <label className="flex items-center gap-2 text-xs text-zinc-200 cursor-pointer p-2 bg-zinc-900/60 rounded-lg border border-zinc-800">
                    <input
                      type="checkbox"
                      checked={triggerOnPlay}
                      onChange={(e) => setTriggerOnPlay(e.target.checked)}
                      className="rounded accent-red-600 w-4 h-4 cursor-pointer"
                    />
                    <span>Trigger on Play Button (▶ Triangle)</span>
                  </label>

                  <div className="space-y-1">
                    <label className="text-xs font-medium text-zinc-300 flex items-center gap-1">
                      <Clock className="w-3 h-3 text-amber-400" /> Hook Delay Seconds
                    </label>
                    <input
                      type="number"
                      min={0}
                      max={120}
                      value={delaySeconds}
                      onChange={(e) => setDelaySeconds(Number(e.target.value))}
                      className="w-full px-3 py-1.5 bg-black/70 border border-zinc-700 focus:border-sky-400 rounded-lg text-xs font-mono text-zinc-100 outline-none"
                    />
                  </div>
                </div>
              </div>
            )}

            <div className="flex items-center justify-between pt-1 text-xs">
              <button
                type="button"
                onClick={onTriggerTestLocker}
                className="text-amber-400 hover:text-amber-300 underline underline-offset-2 flex items-center gap-1 cursor-pointer"
              >
                <Sparkles className="w-3.5 h-3.5" /> Test Preview Locker Modal
              </button>
              <button
                type="button"
                onClick={() => {
                  try {
                    sessionStorage.clear();
                    Object.keys(localStorage).forEach((key) => {
                      if (key.startsWith('unlocked_') || key.startsWith('flixstream_unlocked_')) {
                        localStorage.removeItem(key);
                      }
                    });
                  } catch {
                    // ignore
                  }
                  setRelockedSuccess(true);
                  setTimeout(() => setRelockedSuccess(false), 2500);
                }}
                className="text-cyan-400 hover:text-red-300 underline underline-offset-2 transition cursor-pointer"
              >
                {relockedSuccess ? '✓ All Re-Locked!' : 'Reset Unlock Status (Re-Lock All)'}
              </button>
            </div>
          </div>

          {/* Cloudflare & Source Code Export */}
          <div className="p-4 bg-gradient-to-r from-red-950/40 via-zinc-900 to-zinc-900 border border-red-900/40 rounded-xl space-y-3">
            <div>
              <h3 className="text-xs font-semibold text-zinc-100 flex items-center gap-1.5">
                <Cloud className="w-3.5 h-3.5 text-amber-400" />
                <span>Cloudflare Pages & Source Export</span>
              </h3>
              <p className="text-[11px] text-zinc-400 mt-0.5">
                Download the ready-to-deploy package for Cloudflare Pages or the complete source code.
              </p>
            </div>
            <div className="flex flex-wrap items-center gap-2 pt-1">
              <button
                type="button"
                onClick={handleDownload}
                disabled={downloadingZip}
                className="px-4 py-2.5 bg-gradient-to-r from-amber-600 to-orange-600 hover:from-amber-500 hover:to-orange-500 text-white font-bold text-xs rounded-xl transition flex items-center gap-2 shadow-lg shadow-amber-950/40 cursor-pointer disabled:opacity-50"
              >
                <Download className="w-4 h-4" />
                <span>{downloadingZip ? 'Generating ZIP...' : '📦 Telecharger Code (Cloudflare Pages ZIP)'}</span>
              </button>
            </div>
          </div>

          {/* Actions */}
          <div className="flex items-center justify-between pt-2">
            <button
              type="button"
              onClick={handleResetDefault}
              className="text-xs text-zinc-400 hover:text-zinc-200 transition cursor-pointer"
            >
              Restore Defaults
            </button>
            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={onClose}
                className="px-4 py-2 bg-zinc-800 hover:bg-zinc-700 text-zinc-300 text-xs font-medium rounded-xl transition cursor-pointer"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="px-5 py-2 bg-[#0ea5e9] hover:bg-sky-600 active:scale-95 text-white text-xs font-semibold rounded-xl transition flex items-center gap-1.5 shadow-lg shadow-sky-950/40 cursor-pointer"
              >
                {savedSuccess ? (
                  <>
                    <Check className="w-4 h-4 text-white" />
                    <span>Saved!</span>
                  </>
                ) : (
                  <span>Save Changes</span>
                )}
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
};

src/components/TrailerModal.tsx:
import React, { useEffect, useState } from 'react';
import { X, Youtube, ExternalLink, Loader2 } from 'lucide-react';
import { MediaItem, VideoItem } from '../types';
import { fetchVideos } from '../services/tmdb';

interface TrailerModalProps {
  media: MediaItem;
  onClose: () => void;
  onWatchNow: () => void;
}

export const TrailerModal: React.FC<TrailerModalProps> = ({ media, onClose, onWatchNow }) => {
  const [videos, setVideos] = useState<VideoItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedKey, setSelectedKey] = useState<string | null>(null);

  const mediaType = media.media_type || (media.title ? 'movie' : 'tv');

  useEffect(() => {
    let isMounted = true;
    setLoading(true);
    fetchVideos(mediaType, media.id).then((vids) => {
      if (!isMounted) return;
      setVideos(vids);
      // Prefer Official Trailer or Teaser
      const trailer = vids.find(
        (v) => v.site === 'YouTube' && (v.type === 'Trailer' || v.type === 'Teaser')
      ) || vids.find((v) => v.site === 'YouTube');
      if (trailer) {
        setSelectedKey(trailer.key);
      }
      setLoading(false);
    });

    return () => {
      isMounted = false;
    };
  }, [media.id, mediaType]);

  const title = media.title || media.name || 'Trailer';

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-6 bg-black/85 backdrop-blur-md animate-fade-in">
      <div className="relative w-full max-w-4xl bg-[#181818] border border-zinc-700/60 rounded-2xl shadow-2xl overflow-hidden text-white flex flex-col">
        {/* Header */}
        <div className="px-5 py-3.5 bg-[#202020] border-b border-zinc-800 flex items-center justify-between">
          <div className="flex items-center gap-2.5 overflow-hidden">
            <Youtube className="w-5 h-5 text-sky-400 shrink-0" />
            <span className="font-semibold text-sm sm:text-base truncate">{title} - Official Trailer</span>
          </div>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={onWatchNow}
              className="px-3.5 py-1.5 bg-[#0ea5e9] hover:bg-sky-600 text-white text-xs sm:text-sm font-semibold rounded-lg transition flex items-center gap-1.5 cursor-pointer"
            >
              Watch Full Movie
            </button>
            <button
              type="button"
              onClick={onClose}
              className="p-1.5 text-zinc-400 hover:text-white rounded-lg hover:bg-zinc-800 transition cursor-pointer"
            >
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Video Area */}
        <div className="relative w-full aspect-video bg-black flex items-center justify-center">
          {loading ? (
            <div className="flex flex-col items-center gap-2 text-zinc-400">
              <Loader2 className="w-8 h-8 animate-spin text-sky-400" />
              <span className="text-xs">Loading official trailer...</span>
            </div>
          ) : selectedKey ? (
            <iframe
              src={`https://www.youtube-nocookie.com/embed/${selectedKey}?autoplay=1&rel=0&modestbranding=1`}
              title={`${title} Trailer`}
              className="w-full h-full border-0"
              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
              allowFullScreen
            />
          ) : (
            <div className="flex flex-col items-center gap-3 p-6 text-center text-zinc-400">
              <Youtube className="w-12 h-12 text-zinc-600" />
              <p className="text-sm">Official YouTube trailer not available for this title.</p>
              <a
                href={`https://www.youtube.com/results?search_query=${encodeURIComponent(title + ' trailer')}`}
                target="_blank"
                rel="noreferrer"
                className="px-4 py-2 bg-zinc-800 hover:bg-zinc-700 text-white rounded-lg text-xs flex items-center gap-2 transition"
              >
                Search on YouTube <ExternalLink className="w-3.5 h-3.5" />
              </a>
            </div>
          )}
        </div>

        {/* Alternative trailer selector if multiple exist */}
        {videos.length > 1 && (
          <div className="p-3 bg-[#151515] border-t border-zinc-800 flex items-center gap-2 overflow-x-auto no-scrollbar text-xs">
            <span className="text-zinc-400 shrink-0 font-medium">Clips & Trailers:</span>
            {videos.slice(0, 6).map((vid) => (
              <button
                key={vid.id}
                onClick={() => setSelectedKey(vid.key)}
                className={`px-2.5 py-1 rounded-md shrink-0 transition text-xs truncate max-w-[180px] ${
                  selectedKey === vid.key
                    ? 'bg-sky-500 text-white font-medium'
                    : 'bg-zinc-800 hover:bg-zinc-700 text-zinc-300'
                }`}
              >
                {vid.name}
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

src/components/WatchPartyModal.tsx:
import React, { useState } from 'react';
import { X, Copy, Check, Share2, Users, Send, ExternalLink, Sparkles, MessageSquare } from 'lucide-react';
import { MediaItem } from '../types';

interface WatchPartyModalProps {
  isOpen: boolean;
  onClose: () => void;
  media: MediaItem;
  season?: number;
  episode?: number;
}

export const WatchPartyModal: React.FC<WatchPartyModalProps> = ({
  isOpen,
  onClose,
  media,
  season = 1,
  episode = 1,
}) => {
  const [copied, setCopied] = useState(false);
  const title = media.title || media.name || 'Featured Title';
  const isTv = media.media_type === 'tv' || !!media.first_air_date;

  if (!isOpen) return null;

  // Generate deep-linking watch URL
  const baseUrl = window.location.origin;
  const shareUrl = isTv
    ? `${baseUrl}/?watch=${media.id}&season=${season}&episode=${episode}`
    : `${baseUrl}/?watch=${media.id}`;

  const shareText = isTv
    ? `🍿 Join my Watch Party for "${title}" (Season ${season}, Episode ${episode}) in Ultra HD on BleuStream!`
    : `🍿 Join my Watch Party for "${title}" in Ultra HD on BleuStream!`;

  const handleCopyLink = () => {
    navigator.clipboard.writeText(shareUrl).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2500);
    });
  };

  const handleWhatsApp = () => {
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(`${shareText} ${shareUrl}`)}`, '_blank');
  };

  const handleTelegram = () => {
    window.open(`https://t.me/share/url?url=${encodeURIComponent(shareUrl)}&text=${encodeURIComponent(shareText)}`, '_blank');
  };

  const handleTwitter = () => {
    window.open(`https://twitter.com/intent/tweet?text=${encodeURIComponent(shareText)}&url=${encodeURIComponent(shareUrl)}`, '_blank');
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="relative w-full max-w-lg bg-[#18181b] border border-zinc-700/80 rounded-2xl p-5 sm:p-6 shadow-2xl space-y-5 animate-in zoom-in-95 duration-200">
        {/* Header */}
        <div className="flex items-center justify-between border-b border-zinc-800 pb-4">
          <div className="flex items-center gap-2.5">
            <div className="p-2 bg-sky-500/20 text-sky-400 rounded-xl">
              <Users className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-base sm:text-lg font-black text-white flex items-center gap-2">
                <span>Watch Party & Cinema Share</span>
                <span className="px-1.5 py-0.5 bg-sky-500 text-white text-[9px] font-black uppercase rounded tracking-wider">
                  LIVE SYNC
                </span>
              </h3>
              <p className="text-xs text-zinc-400">
                Invite friends to stream <span className="text-zinc-200 font-semibold">{title}</span> together
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 text-zinc-400 hover:text-white bg-zinc-800 hover:bg-zinc-700 rounded-lg transition cursor-pointer"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Room Info Card */}
        <div className="bg-zinc-900/90 border border-zinc-800 rounded-xl p-3.5 space-y-2">
          <div className="flex items-center justify-between text-xs">
            <span className="text-zinc-400">Current Stream:</span>
            <span className="text-white font-bold truncate max-w-[240px]">
              {title} {isTv ? `• S${season}:E${episode}` : ''}
            </span>
          </div>
          <div className="flex items-center justify-between text-xs">
            <span className="text-zinc-400">Playback Quality:</span>
            <span className="text-emerald-400 font-semibold flex items-center gap-1">
              <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse" />
              1080p Ultra HD / Zero Lag
            </span>
          </div>
        </div>

        {/* Share Link Copy Field */}
        <div className="space-y-1.5">
          <label className="text-xs font-semibold text-zinc-300 block">
            Direct Cinema Room Link:
          </label>
          <div className="flex items-center gap-2">
            <input
              type="text"
              readOnly
              value={shareUrl}
              className="flex-1 bg-black/70 border border-zinc-700 rounded-xl px-3 py-2 text-xs text-zinc-300 font-mono truncate focus:outline-none focus:border-sky-500"
            />
            <button
              type="button"
              onClick={handleCopyLink}
              className={`px-4 py-2 rounded-xl text-xs font-bold transition flex items-center gap-1.5 shrink-0 cursor-pointer ${
                copied
                  ? 'bg-emerald-600 text-white'
                  : 'bg-[#0ea5e9] hover:bg-sky-600 text-white shadow-lg shadow-sky-950/40'
              }`}
            >
              {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
              <span>{copied ? 'Copied!' : 'Copy Link'}</span>
            </button>
          </div>
          {copied && (
            <p className="text-[11px] text-emerald-400 animate-in fade-in">
              ✓ Room link copied! Send it to your friends to start watching together.
            </p>
          )}
        </div>

        {/* 1-Click Social Sharing */}
        <div className="space-y-2 pt-1">
          <span className="text-[11px] font-bold uppercase tracking-wider text-zinc-400 block">
            Share Directly:
          </span>
          <div className="grid grid-cols-3 gap-2">
            <button
              type="button"
              onClick={handleWhatsApp}
